DELIMITER ;;
CREATE PROCEDURE `sis_permiso_asignar`(IN p_id_rol INT, IN p_id_accion INT)
BEGIN
    INSERT IGNORE INTO sis_permiso (id_rol, id_accion) VALUES (p_id_rol, p_id_accion);
END ;;
DELIMITER ;
