DELIMITER ;;
CREATE PROCEDURE `sis_rol_listar`()
BEGIN
    SELECT id_rol, nombre, descripcion FROM sis_rol WHERE estado_registro = 'ACTIVO' ORDER BY id_rol ASC;
END ;;
