DELIMITER ;;
CREATE PROCEDURE `sis_usuario_eliminar`(IN p_id INT)
BEGIN
    UPDATE sis_usuario SET estado_registro = 'ELIMINADO' WHERE id_usuario = p_id;
END ;;
