-- ==============================================================================
-- 2. MÓDULO PLANILLA — Paso 1: catálogos oficiales de SUNAT
-- ==============================================================================
-- Base del módulo de planillas (sueldos, CTS, gratificaciones — ver
-- bd/PLAN_MODULO_PLANILLAS.md). Este primer paso solo trae los catálogos que
-- publica SUNAT, porque TODO lo demás depende de ellos: sin el código PLAME
-- correcto, la declaración se rechaza.
--
-- Fuente: Anexo 2 "Tablas Paramétricas de la Planilla Electrónica"
--         https://orientacion.sunat.gob.pe/7086-12-tablas-parametricas
--         Archivo descargado y versionado en bd/sunat-tablas-parametricas/
-- ==============================================================================


-- ------------------------------------------------------------------------------
-- planilla_sunat_descarga — bitácora de versiones del archivo de SUNAT
-- ------------------------------------------------------------------------------
-- SUNAT republica las tablas paramétricas entre 1 y 4 veces al año (verificado
-- contra el histórico del Wayback Machine: feb-2021, abr/jun/set-2022, nov-2023,
-- ene-2024, oct-2024, ene-2025, ago-2026). No hay API: hay que leer el enlace de
-- la página, porque el nombre Y la carpeta cambian en cada publicación
-- (antes /inline-files/Anexo2_tablas_parametricas_Enero25_0.xlsx,
--  ahora  /2026-08/tablas_parametricas_actualizada-25.08.26.xlsx).
--
-- Una fila por VERSIÓN detectada, no por corrida del job: si fuera por corrida
-- habría ~365 filas al año diciendo "no cambió nada". Por eso el job actualiza
-- fecha_ultima_verificacion en el sitio cuando no encuentra novedad.
CREATE TABLE `planilla_sunat_descarga` (
  `id_descarga` int NOT NULL AUTO_INCREMENT,
  `url_origen` varchar(500) NOT NULL COMMENT 'URL completa del .xlsx. Cambia de nombre y carpeta en cada publicación, por eso se guarda entera',
  `nombre_archivo_sunat` varchar(255) NOT NULL COMMENT 'Ej: tablas_parametricas_actualizada-25.08.26.xlsx',
  `last_modified_http` datetime DEFAULT NULL COMMENT 'Header Last-Modified del servidor de SUNAT',
  `etag` varchar(100) DEFAULT NULL COMMENT 'Header ETag: permite detectar cambio sin descargar el archivo completo',
  `hash_sha256` char(64) NOT NULL COMMENT 'Del archivo descargado. UNIQUE: SUNAT republica el mismo contenido con otro nombre y eso NO es una versión nueva',
  `tamano_bytes` int DEFAULT NULL,
  `archivo_ruta` varchar(255) DEFAULT NULL COMMENT 'Relativa a storage-privado/ (NUNCA uploads/, no es pública)',
  `estado` enum('DETECTADA','DESCARGADA','IMPORTADA','DESCARTADA','ERROR') NOT NULL DEFAULT 'DETECTADA',
  `es_vigente` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'La versión actualmente cargada en planilla_concepto/planilla_sunat_catalogo. Solo una fila en 1',
  `conceptos_total` int NOT NULL DEFAULT 0,
  `conceptos_nuevos` int NOT NULL DEFAULT 0,
  `conceptos_modificados` int NOT NULL DEFAULT 0,
  `conceptos_retirados` int NOT NULL DEFAULT 0,
  `resumen_cambios` json DEFAULT NULL COMMENT 'Diff contra la versión vigente. Se muestra para que un humano apruebe ANTES de importar: un import a ciegas puede alterar cálculos de planillas ya cerradas',
  `mensaje_error` text DEFAULT NULL COMMENT 'Detalle si estado=ERROR, para revisión manual sin repetir el intento a ciegas',
  `fecha_deteccion` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_descarga` datetime DEFAULT NULL,
  `fecha_importacion` datetime DEFAULT NULL,
  `fecha_ultima_verificacion` datetime DEFAULT NULL COMMENT 'Se actualiza en cada corrida del job aunque no haya novedad, para saber cuándo se revisó por última vez',
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_descarga`),
  UNIQUE KEY `uk_planilla_sunat_descarga_hash` (`hash_sha256`),
  KEY `ix_planilla_sunat_descarga_vigente` (`es_vigente`),
  KEY `fk_planilla_sunat_descarga_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_sunat_descarga_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Bitácora de versiones del Anexo 2 (tablas paramétricas) descargado de SUNAT.';


-- ------------------------------------------------------------------------------
-- planilla_concepto — Tabla 22: "Ingresos, Tributos y Descuentos" del PDT PLAME
-- ------------------------------------------------------------------------------
-- Es el corazón del módulo: 311 conceptos con su matriz de afectación oficial.
--
-- Las columnas afecto_* NO se hardcodean en el motor de cálculo, se leen de acá.
-- Ejemplo concreto: la gratificación (0406/0407) sale de SUNAT como NO afecta a
-- EsSalud/ONP/AFP y SÍ afecta a renta de 5ta — es la inafectación de la Ley 30334.
-- Si mañana cambia la ley, SUNAT publica archivo nuevo y se reimporta, sin tocar
-- una línea de código.
--
-- base_cts / base_gratificacion / base_vacaciones son la excepción: NO vienen de
-- SUNAT (son reglas del MTPE) y las define el estudio. Por eso la reimportación
-- no las pisa.
CREATE TABLE `planilla_concepto` (
  `id_concepto` int NOT NULL AUTO_INCREMENT,
  `codigo_plame` char(4) NOT NULL COMMENT 'Código oficial de 4 dígitos. Va tal cual al archivo plano del PLAME',
  `nombre` varchar(255) NOT NULL,
  `grupo_sunat` varchar(120) DEFAULT NULL COMMENT 'Agrupación de la Tabla 22: INGRESOS, INGRESOS: ASIGNACIONES, DESCUENTOS AL TRABAJADOR...',
  `tipo` enum('INGRESO','DESCUENTO','APORTE_EMPLEADOR') NOT NULL,
  `solo_sector_publico` tinyint(1) NOT NULL DEFAULT 0 COMMENT '117 de los 311 son del D.Leg. 276 y BET fijo. Se cargan igual, pero la UI los oculta por defecto',

  -- Afectaciones OFICIALES: vienen de la matriz de la Tabla 22, no se editan a mano.
  `es_remunerativo` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Derivado: afecto a EsSalud regular O a SNP O a SPP',
  `afecto_renta_quinta` tinyint(1) NOT NULL DEFAULT 0,
  `afecto_essalud` tinyint(1) NOT NULL DEFAULT 0,
  `afecto_sctr` tinyint(1) NOT NULL DEFAULT 0,
  `afecto_senati` tinyint(1) NOT NULL DEFAULT 0,
  `afecto_onp` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Sistema Nacional de Pensiones D.L. 19990',
  `afecto_afp` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Sistema Privado de Pensiones',
  `afecto_ies` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Impuesto Extraordinario de Solidaridad',

  -- Reglas laborales PROPIAS (MTPE): las define el estudio, la reimportación no las toca.
  `base_cts` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Entra a la remuneración computable de CTS',
  `base_gratificacion` tinyint(1) NOT NULL DEFAULT 0,
  `base_vacaciones` tinyint(1) NOT NULL DEFAULT 0,

  -- Operativos.
  `tipo_calculo` enum('FIJO','PORCENTAJE','FORMULA','MANUAL') NOT NULL DEFAULT 'MANUAL',
  `formula` varchar(255) DEFAULT NULL,
  `porcentaje_default` decimal(7,4) DEFAULT NULL,
  `orden_impresion` int NOT NULL DEFAULT 0 COMMENT 'Orden en la boleta de pago',
  `editable` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0 = vino de SUNAT, la reimportación lo pisa. 1 = concepto propio del estudio, no se toca',
  `id_descarga_origen` int DEFAULT NULL COMMENT 'De qué versión del archivo de SUNAT salió este concepto',

  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_concepto`),
  UNIQUE KEY `uk_planilla_concepto_codigo` (`codigo_plame`),
  KEY `ix_planilla_concepto_tipo` (`tipo`, `solo_sector_publico`, `estado_registro`),
  KEY `fk_planilla_concepto_descarga` (`id_descarga_origen`),
  KEY `fk_planilla_concepto_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_concepto_descarga` FOREIGN KEY (`id_descarga_origen`) REFERENCES `planilla_sunat_descarga` (`id_descarga`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_concepto_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Tabla 22 de SUNAT: conceptos de ingresos, tributos y descuentos del PDT PLAME.';


-- ------------------------------------------------------------------------------
-- planilla_sunat_catalogo — las otras 20+ tablas paramétricas, en una sola
-- ------------------------------------------------------------------------------
-- Una tabla genérica y no 20 tablas separadas: son catálogos de pura forma
-- código -> descripción, SUNAT los publica en un ÚNICO archivo y los actualiza
-- juntos. Así hay un loader, un CRUD y una reimportación; con 20 tablas serían
-- 20 migraciones cada vez que SUNAT publique.
--
-- planilla_concepto (T22) es la excepción y va aparte: lleva 15 columnas de
-- afectación más las reglas propias del estudio, no cabe en la forma genérica.
--
-- IMPORTANTE: se guarda el CÓDIGO OFICIAL de SUNAT ('03'), no una etiqueta
-- legible ('EMPLEADO'). El archivo plano del PLAME y del T-Registro exige el
-- código exacto; guardar la etiqueta obliga a un mapeo manual en cada
-- exportación, que es justo donde se rompe.
CREATE TABLE `planilla_sunat_catalogo` (
  `id_catalogo` int NOT NULL AUTO_INCREMENT,
  `tabla_num` smallint NOT NULL COMMENT 'Número de tabla del Anexo 2: 3, 8, 11, 12, 13, 15, 17, 18, 21, 24, 28, 30, 32, 33, 36...',
  `tabla_nombre` varchar(120) NOT NULL COMMENT 'Ej: "Tipo de documento de identidad"',
  `codigo` varchar(10) NOT NULL COMMENT 'Código oficial de SUNAT, tal cual va al archivo plano',
  `descripcion` varchar(255) NOT NULL,
  `descripcion_abreviada` varchar(120) DEFAULT NULL,
  `aplica_sector_privado` tinyint(1) NOT NULL DEFAULT 1,
  `aplica_sector_publico` tinyint(1) NOT NULL DEFAULT 1,
  `vigente` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'SUNAT deshabilita códigos sin borrarlos (ej. tipo doc 11 - Partida de nacimiento, deshabilitado el 19.05.2013)',
  `id_descarga_origen` int DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_catalogo`),
  UNIQUE KEY `uk_planilla_sunat_catalogo` (`tabla_num`, `codigo`),
  KEY `ix_planilla_sunat_catalogo_tabla` (`tabla_num`, `vigente`, `estado_registro`),
  KEY `fk_planilla_sunat_catalogo_descarga` (`id_descarga_origen`),
  KEY `fk_planilla_sunat_catalogo_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_sunat_catalogo_descarga` FOREIGN KEY (`id_descarga_origen`) REFERENCES `planilla_sunat_descarga` (`id_descarga`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_sunat_catalogo_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Tablas paramétricas del Anexo 2 de SUNAT (todas menos la 22), en formato genérico código-descripción.';


-- ------------------------------------------------------------------------------
-- Permisos: módulo PLANILLA
-- ------------------------------------------------------------------------------
-- Solo las acciones de este primer paso (catálogos). Las de trabajadores,
-- planilla mensual y beneficios sociales se agregan en sus propios pasos.
INSERT INTO `sis_modulo` (`nombre`, `etiqueta`, `estado_registro`) VALUES
('PLANILLA', 'Planilla', 'ACTIVO');

SET @id_modulo_planilla = (SELECT id_modulo FROM sis_modulo WHERE nombre = 'PLANILLA');

INSERT INTO `sis_accion` (`id_modulo`, `codigo_accion`, `descripcion`, `tipo_operacion`, `estado_registro`) VALUES
(@id_modulo_planilla, 'ver_concepto_plame', 'Ver el catálogo de conceptos del PDT PLAME (Tabla 22)', 'READ', 'ACTIVO'),
(@id_modulo_planilla, 'crear_concepto_plame', 'Crear un concepto propio del estudio, fuera de la Tabla 22', 'CREATE', 'ACTIVO'),
(@id_modulo_planilla, 'editar_concepto_plame', 'Editar un concepto: bases de CTS/gratificación/vacaciones, fórmula, orden en boleta', 'UPDATE', 'ACTIVO'),
(@id_modulo_planilla, 'eliminar_concepto_plame', 'Dar de baja un concepto propio del estudio', 'DELETE', 'ACTIVO'),
(@id_modulo_planilla, 'ver_tablas_sunat', 'Ver las tablas paramétricas de SUNAT y el historial de versiones descargadas', 'READ', 'ACTIVO'),
(@id_modulo_planilla, 'importar_tablas_sunat', 'Descargar e importar una versión nueva de las tablas paramétricas de SUNAT', 'SPECIAL', 'ACTIVO');

INSERT INTO `sis_permiso` (`id_rol`, `id_accion`, `estado_registro`)
SELECT 1, id_accion, 'ACTIVO' FROM sis_accion WHERE id_modulo = @id_modulo_planilla;

-- ------------------------------------------------------------------------------
-- Semilla de conceptos PLAME (Tabla 22 de SUNAT)
-- ------------------------------------------------------------------------------
-- Bloque GENERADO. Se regenera con:
--   node scripts/generar-seed-conceptos-plame.js
-- que lee bd/sunat-tablas-parametricas/tablas_2026.xlsx y reemplaza lo que hay
-- entre los dos marcadores de abajo. No editar a mano: el próximo run lo pisa.
-- >>> INICIO BLOQUE GENERADO: planilla_concepto — no editar a mano
-- ==============================================================================
-- Semilla planilla_concepto — SUNAT Tabla 22 "Ingresos, Tributos y Descuentos"
--
-- GENERADO — no editar a mano. Re-correr:
--   node scripts/generar-seed-conceptos-plame.js
--
-- Fuente oficial: bd/sunat-tablas-parametricas/tablas_2026.xlsx
--                 (tablas_parametricas_actualizada-25.08.26.xlsx de SUNAT)
--                 https://orientacion.sunat.gob.pe/7086-12-tablas-parametricas
--
-- Total: 311 conceptos — 194 del sector privado, 117 del público.
-- Los del sector público van con solo_sector_publico=1: la UI los oculta por
-- defecto, pero quedan declarados por si el estudio toma un cliente del Estado.
--
-- El nombre del código 0406 viene con la celda combinada VACÍA en el xlsx oficial;
-- se completó desde el PDF "Tabla N22 Definición Conceptos Plame" (01/10/2025).
--
-- editable=0 -> vino de SUNAT: la reimportación lo pisa.
-- editable=1 -> concepto propio del estudio: la reimportación NO lo toca.
--
-- Idempotente. El ON DUPLICATE KEY a propósito NO pisa base_cts / base_gratificacion
-- / base_vacaciones: esas son reglas del MTPE que define el estudio, no SUNAT, y
-- una reimportación no debe borrar ese trabajo.
-- ==============================================================================
INSERT INTO planilla_concepto
 (codigo_plame, nombre, grupo_sunat, tipo, solo_sector_publico,
  es_remunerativo, afecto_renta_quinta, afecto_essalud, afecto_sctr, afecto_senati,
  afecto_onp, afecto_afp, afecto_ies, orden_impresion, editable, id_usuario_crea)
