-- <<< FIN BLOQUE GENERADO: planilla_concepto


-- ==============================================================================
-- 3. MÓDULO PLANILLA — Paso 2: catálogos que SUNAT no publica
-- ==============================================================================
-- El Paso 1 trajo todo lo que SUNAT publica (conceptos PLAME, ubigeo, ocupaciones,
-- bancos...). Pero el cálculo de una planilla necesita datos que SUNAT NO publica
-- porque no son tributarios: son laborales (MTPE/PRODUCE), previsionales (SBS) o
-- decisiones del propio estudio.
--
-- Sin estas tablas el sistema sabe que la asignación familiar está afecta a EsSalud
-- —eso lo dice SUNAT— pero no sabe cuánto es EsSalud, ni cuánto es la asignación
-- familiar, ni cómo distinguir un trabajador MYPE de uno del régimen general.
-- Esa última distinción es el corazón del módulo y no está en nada de lo descargado.
--
-- IMPORTANTE — columnas `verificado` / `fuente`:
-- No todos estos datos salen de un archivo oficial descargable. Los factores MYPE
-- están en la ley y son estables; las tasas AFP las publica la SBS y cambian cada
-- cuatrimestre. Una tasa mal puesta descuenta mal a TODOS los trabajadores de TODAS
-- las empresas, así que cada fila declara si fue verificada contra la fuente oficial
-- y de dónde salió. La UI debe advertir sobre las que tengan verificado = 0.
-- ==============================================================================


-- ------------------------------------------------------------------------------
-- planilla_regimen_laboral — la tabla que manda sobre todo el cálculo
-- ------------------------------------------------------------------------------
-- Con esto NINGÚN `if (regimen === 'MYPE')` queda hardcodeado en el motor: la
-- diferencia entre Régimen General, Pequeña Empresa y Microempresa es data, no
-- lógica. Si PRODUCE cambia una regla, se edita la fila y no se despliega nada.
CREATE TABLE `planilla_regimen_laboral` (
  `id_regimen` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(30) NOT NULL COMMENT 'REGIMEN_GENERAL, PEQUENA_EMPRESA, MICROEMPRESA',
  `nombre` varchar(120) NOT NULL,
  `cod_regimen_laboral_sunat` varchar(10) DEFAULT NULL COMMENT 'Código de la Tabla 33 que se declara en el T-Registro (todos son 01: privado general D.Leg. 728)',
  `vigencia_desde` date NOT NULL,
  `dias_vacaciones` smallint NOT NULL COMMENT '30 general, 15 pequeña y micro',
  `factor_gratificacion` decimal(4,2) NOT NULL COMMENT '1.00 general, 0.50 pequeña, 0.00 micro (no le corresponde)',
  `factor_cts` decimal(4,2) NOT NULL COMMENT '1.00 general, 0.50 pequeña, 0.00 micro (no le corresponde)',
  `aplica_asignacion_familiar` tinyint(1) NOT NULL DEFAULT 1,
  `aplica_essalud` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'La microempresa va al SIS, no a EsSalud regular',
  `pension_obligatoria` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'En microempresa la afiliación al SPP/SNP es opcional',
  `dias_indemnizacion_por_anio` smallint NOT NULL DEFAULT 0 COMMENT 'Despido arbitrario: 45 días (1.5 rem) general, 20 pequeña, 10 micro',
  `tope_dias_indemnizacion` smallint NOT NULL DEFAULT 0 COMMENT '360 días (12 rem) general, 120 pequeña, 90 micro',
  `base_legal` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_regimen`),
  UNIQUE KEY `uk_planilla_regimen_codigo` (`codigo`),
  KEY `fk_planilla_regimen_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_regimen_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Regímenes laborales del sector privado y los factores que diferencian su cálculo de CTS, gratificación y vacaciones.';


-- ------------------------------------------------------------------------------
-- planilla_afp — las cuatro AFP del mercado peruano
-- ------------------------------------------------------------------------------
CREATE TABLE `planilla_afp` (
  `id_afp` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(20) NOT NULL,
  `nombre` varchar(120) NOT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_afp`),
  UNIQUE KEY `uk_planilla_afp_codigo` (`codigo`),
  KEY `fk_planilla_afp_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_afp_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Administradoras de Fondos de Pensiones.';


-- ------------------------------------------------------------------------------
-- planilla_afp_tasa — las tasas del SPP, con vigencia por fecha
-- ------------------------------------------------------------------------------
-- Van con vigencia y no como columnas de planilla_afp porque la SBS las actualiza
-- CADA CUATRIMESTRE. Recalcular una planilla de marzo con las tasas de julio daría
-- un resultado distinto al que se declaró: el motor busca la tasa vigente al periodo.
CREATE TABLE `planilla_afp_tasa` (
  `id_afp_tasa` int NOT NULL AUTO_INCREMENT,
  `id_afp` int NOT NULL,
  `vigencia_desde` date NOT NULL,
  `vigencia_hasta` date DEFAULT NULL COMMENT 'NULL = vigente hasta nuevo aviso',
  `pct_aporte_obligatorio` decimal(7,4) NOT NULL DEFAULT 10.0000 COMMENT 'Fijo por ley: 10% del sueldo, va al fondo del trabajador',
  `pct_comision_flujo` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Sobre la remuneración. Aplica a quien eligió comisión por flujo',
  `pct_comision_mixta_flujo` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Componente sobre flujo de la comisión mixta: 0% para las 4 AFP desde feb-2023',
  `pct_comision_mixta_saldo` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Cargo ANUAL sobre el saldo. No se descuenta en planilla, lo cobra la AFP al fondo',
  `pct_prima_seguro` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Seguro de invalidez y sobrevivencia. Igual para las 4 AFP',
  `tope_remuneracion_asegurable` decimal(12,2) DEFAULT NULL COMMENT 'La prima se calcula hasta este tope, no sobre el sueldo completo',
  `verificado` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 = NO confirmado contra la SBS. La UI debe advertirlo antes de calcular en serio',
  `fuente` varchar(255) DEFAULT NULL COMMENT 'De dónde salió el dato, para poder rastrearlo',
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_afp_tasa`),
  UNIQUE KEY `uk_planilla_afp_tasa_vigencia` (`id_afp`,`vigencia_desde`),
  KEY `ix_planilla_afp_tasa_busqueda` (`id_afp`,`vigencia_desde`,`vigencia_hasta`),
  KEY `fk_planilla_afp_tasa_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_afp_tasa_afp` FOREIGN KEY (`id_afp`) REFERENCES `planilla_afp` (`id_afp`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_afp_tasa_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Tasas del SPP por AFP y periodo de vigencia (la SBS las actualiza cada cuatrimestre).';


-- ------------------------------------------------------------------------------
-- planilla_parametro_laboral — RMV, UIT y tasas de aportes
-- ------------------------------------------------------------------------------
-- Tabla propia y no `parametro_tributario` (que ya existe) porque esa es
-- (anio, codigo) y la RMV cambia a mitad de año: acá hace falta vigencia por FECHA.
CREATE TABLE `planilla_parametro_laboral` (
  `id_parametro` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(60) NOT NULL COMMENT 'RMV, UIT, ESSALUD_PCT, ONP_PCT, ASIGNACION_FAMILIAR_PCT...',
  `nombre` varchar(200) NOT NULL,
  `valor` decimal(14,4) NOT NULL,
  `unidad` enum('SOLES','PORCENTAJE','DIAS','FACTOR') NOT NULL DEFAULT 'SOLES',
  `vigencia_desde` date NOT NULL,
  `vigencia_hasta` date DEFAULT NULL COMMENT 'NULL = vigente hasta nuevo aviso',
  `base_legal` varchar(255) DEFAULT NULL,
  `verificado` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 = NO confirmado contra la norma oficial. La UI debe advertirlo',
  `fuente` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_parametro`),
  UNIQUE KEY `uk_planilla_parametro_vigencia` (`codigo`,`vigencia_desde`),
  KEY `ix_planilla_parametro_busqueda` (`codigo`,`vigencia_desde`,`vigencia_hasta`),
  KEY `fk_planilla_parametro_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_parametro_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Parámetros laborales con vigencia por fecha (RMV, UIT, tasas de aportes y descuentos).';


-- ------------------------------------------------------------------------------
-- planilla_escala_renta_quinta — tramos del Impuesto a la Renta de 5ta
-- ------------------------------------------------------------------------------
-- Los tramos se expresan en UIT y no en soles a propósito: la ley los define así, y
-- cuando cambia la UIT los montos se recalculan solos sin tocar esta tabla.
CREATE TABLE `planilla_escala_renta_quinta` (
  `id_escala` int NOT NULL AUTO_INCREMENT,
  `anio` smallint NOT NULL,
  `tramo` tinyint NOT NULL,
  `uit_desde` decimal(8,2) NOT NULL COMMENT 'Límite inferior en UIT (exclusivo)',
  `uit_hasta` decimal(8,2) DEFAULT NULL COMMENT 'Límite superior en UIT (inclusivo). NULL = sin tope',
  `tasa` decimal(7,4) NOT NULL COMMENT 'Porcentaje aplicable al exceso sobre uit_desde',
  `base_legal` varchar(255) DEFAULT NULL,
  `verificado` tinyint(1) NOT NULL DEFAULT 0,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_escala`),
  UNIQUE KEY `uk_planilla_escala_anio_tramo` (`anio`,`tramo`),
  KEY `fk_planilla_escala_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_escala_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Escala progresiva acumulativa del Impuesto a la Renta de quinta categoría (Art. 53 LIR).';


-- ------------------------------------------------------------------------------
-- planilla_banco — bancos para abono de haberes, CTS y telecrédito
-- ------------------------------------------------------------------------------
-- Se siembra de la Tabla 36 de SUNAT (ya cargada en planilla_sunat_catalogo), pero
-- vive aparte porque lleva algo que SUNAT no da: qué formato de archivo plano de
-- telecrédito usa cada banco.
CREATE TABLE `planilla_banco` (
  `id_banco` int NOT NULL AUTO_INCREMENT,
  `codigo_sunat` varchar(10) NOT NULL COMMENT 'Código de la Tabla 36 (002 BCP, 003 Interbank, 009 Scotiabank, 011 BBVA)',
  `nombre` varchar(150) NOT NULL,
  `formato_telecredito` enum('BCP','INTERBANK','BBVA','SCOTIABANK','NINGUNO') NOT NULL DEFAULT 'NINGUNO',
  `longitud_cuenta` tinyint DEFAULT NULL,
  `longitud_cci` tinyint NOT NULL DEFAULT 20,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_banco`),
  UNIQUE KEY `uk_planilla_banco_codigo` (`codigo_sunat`),
  KEY `fk_planilla_banco_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_banco_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Entidades financieras para abono de haberes, depósito de CTS y archivos de telecrédito.';


-- ------------------------------------------------------------------------------
-- planilla_tareo_marca — la leyenda del tareo diario
-- ------------------------------------------------------------------------------
-- Es la ficha "Tareo" del Excel: se llena día por día con un código (A = asistió,
-- F = falta, F1 = feriado...) y el botón "Calcular datos" cuenta los días por marca.
-- Cada marca declara QUÉ cuenta, para que el conteo no dependa de un switch en el
-- código: agregar una marca nueva es insertar una fila.
CREATE TABLE `planilla_tareo_marca` (
  `id_marca` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(5) NOT NULL COMMENT 'Lo que se escribe en la casilla del día: A, F, F1...',
  `nombre` varchar(120) NOT NULL,
  `computa_dia_laborado` tinyint(1) NOT NULL DEFAULT 0,
  `computa_falta` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Falta injustificada: descuenta y no es computable para beneficios',
  `computa_feriado` tinyint(1) NOT NULL DEFAULT 0,
  `computa_descanso` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Descanso semanal obligatorio',
  `computa_subsidio` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Descanso médico / maternidad: lo paga EsSalud, no el empleador',
  `computa_vacaciones` tinyint(1) NOT NULL DEFAULT 0,
  `computa_licencia_con_goce` tinyint(1) NOT NULL DEFAULT 0,
  `computa_licencia_sin_goce` tinyint(1) NOT NULL DEFAULT 0,
  `es_computable_beneficios` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Si el día suma para CTS, gratificación y vacaciones',
  `cod_tipo_suspension_sunat` varchar(10) DEFAULT NULL COMMENT 'Tabla 21, para declarar la suspensión en el PLAME',
  `color_hex` varchar(7) DEFAULT NULL,
  `orden` smallint NOT NULL DEFAULT 0,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_marca`),
  UNIQUE KEY `uk_planilla_tareo_marca_codigo` (`codigo`),
  KEY `fk_planilla_tareo_marca_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_tareo_marca_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Leyenda del tareo diario: qué significa cada código y qué cuenta para el cálculo.';


