-- ---------- Tasas AFP ----------
-- ⚠️ verificado = 0 — NO CONFIRMADAS CONTRA LA SBS.
-- El portal de la SBS no se dejó leer automáticamente (cadena de redirecciones), así
-- que estos valores salen de fuentes secundarias. El aporte obligatorio de 10% sí es
-- de ley y no cambia; lo que hay que confirmar son las comisiones y la prima.
--
-- ANTES DE CALCULAR EN PRODUCCIÓN: abrir
--   https://www.sbs.gob.pe  ->  Sistema Privado de Pensiones  ->  Tasas
-- y corregir. Una comisión mal puesta descuenta mal a TODOS los trabajadores de
-- TODAS las empresas del estudio, y el error recién se ve en la boleta.
--
-- La comisión mixta tiene componente sobre flujo 0% en las 4 AFP desde feb-2023; el
-- cargo sobre saldo es ANUAL y lo cobra la AFP al fondo, NO se descuenta en planilla
-- (se guarda solo como referencia informativa).
INSERT INTO `planilla_afp_tasa`
 (`id_afp`, `vigencia_desde`, `vigencia_hasta`, `pct_aporte_obligatorio`,
  `pct_comision_flujo`, `pct_comision_mixta_flujo`, `pct_comision_mixta_saldo`,
  `pct_prima_seguro`, `tope_remuneracion_asegurable`, `verificado`, `fuente`, `id_usuario_crea`)
SELECT a.id_afp, '2026-01-01', NULL, 10.0000, t.flujo, 0.0000, t.saldo, 1.3700, 12209.11, 0,
       'Fuente secundaria, sin confirmar contra la SBS (26/08/2026)', 1
FROM `planilla_afp` a
JOIN (
  SELECT 'HABITAT'   AS cod, 1.4700 AS flujo, 1.2500 AS saldo
  UNION ALL SELECT 'INTEGRA',   1.5500, 0.7800
  UNION ALL SELECT 'PRIMA',     1.6000, 1.2500
  UNION ALL SELECT 'PROFUTURO', 1.6900, 0.6800
) t ON t.cod = a.codigo
ON DUPLICATE KEY UPDATE `pct_comision_flujo` = VALUES(`pct_comision_flujo`);


