-- ---------- Bancos ----------
-- Se siembran de la Tabla 36 de SUNAT, ya cargada en planilla_sunat_catalogo: así los
-- códigos coinciden con los que exige el archivo plano y no hay que transcribirlos.
INSERT INTO `planilla_banco` (`codigo_sunat`, `nombre`, `formato_telecredito`, `longitud_cci`, `id_usuario_crea`)
SELECT c.codigo, c.descripcion,
       CASE c.codigo
         WHEN '002' THEN 'BCP'
         WHEN '003' THEN 'INTERBANK'
         WHEN '009' THEN 'SCOTIABANK'
         WHEN '011' THEN 'BBVA'
         ELSE 'NINGUNO'
       END,
       20, 1
FROM `planilla_sunat_catalogo` c
WHERE c.tabla_num = 36 AND c.estado_registro = 'ACTIVO'
ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);


