-- ==============================================================================
-- 4. MÓDULO PLANILLA — Paso 3: configuración por empresa y padrón de trabajadores
-- ==============================================================================
-- Con los pasos 1 y 2 el sistema ya sabe CÓMO calcular. Falta A QUIÉN.
--
-- La ficha del cliente (`empresa`) no se toca ni se duplica: acá cuelga lo que es
-- exclusivamente laboral (tipo de seguro, SCTR, SENATI, jornada) y el padrón.
-- ==============================================================================


-- ------------------------------------------------------------------------------
-- planilla_empresa_config — lo laboral de cada empresa cliente
-- ------------------------------------------------------------------------------
-- 1:1 con `empresa`. Va aparte y no como columnas nuevas en `empresa` porque esa
-- tabla es del módulo de Vencimientos y la comparten los dos módulos: agregarle
-- doce columnas laborales la volvería un cajón de sastre.
CREATE TABLE `planilla_empresa_config` (
  `id_config` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int NOT NULL,
  `id_regimen_default` int DEFAULT NULL COMMENT 'Régimen que se propone al dar de alta un trabajador. Cada trabajador puede tener otro',

  `cod_regimen_salud` varchar(10) NOT NULL DEFAULT '00' COMMENT 'Tabla 32: 00 EsSalud regular, 01 EsSalud + EPS',
  `pct_credito_eps` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Crédito contra el aporte a EsSalud cuando la empresa tiene EPS',

  `afecto_senati` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Solo empresas manufactureras con más de 20 trabajadores (Ley 26272)',
  `pct_senati` decimal(7,4) NOT NULL DEFAULT 0.7500,

  `afecto_sctr` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Solo actividades de riesgo del Anexo 5 del D.S. 009-97-SA',
  `tasa_sctr_salud` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Varía por nivel de riesgo: se pacta con la aseguradora',
  `tasa_sctr_pension` decimal(7,4) NOT NULL DEFAULT 0.0000,

  `horas_jornada` decimal(4,2) NOT NULL DEFAULT 8.00,
  `dias_mes` smallint NOT NULL DEFAULT 30 COMMENT 'Divisor para el valor diario. 30 es la práctica estándar',
  `pct_adelanto_quincena` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Ficha "Entrada de datos" del Excel: % del neto que se adelanta en quincena',

  `id_banco_haberes` int DEFAULT NULL COMMENT 'Banco desde el que se paga la planilla (para el archivo de telecrédito)',
  `cuenta_cargo_telecredito` varchar(30) DEFAULT NULL,
  `codigo_establecimiento_sunat` varchar(10) DEFAULT NULL COMMENT 'Establecimiento declarado en el T-Registro',

  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_config`),
  UNIQUE KEY `uk_planilla_empresa_config` (`id_empresa`),
  KEY `fk_planilla_empresa_config_regimen` (`id_regimen_default`),
  KEY `fk_planilla_empresa_config_banco` (`id_banco_haberes`),
  KEY `fk_planilla_empresa_config_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_empresa_config_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_empresa_config_regimen` FOREIGN KEY (`id_regimen_default`) REFERENCES `planilla_regimen_laboral` (`id_regimen`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_empresa_config_banco` FOREIGN KEY (`id_banco_haberes`) REFERENCES `planilla_banco` (`id_banco`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_empresa_config_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Configuración laboral de cada empresa cliente (seguro, SCTR, SENATI, jornada).';


-- ------------------------------------------------------------------------------
-- planilla_trabajador — el padrón
-- ------------------------------------------------------------------------------
-- Los `cod_*` guardan el CÓDIGO OFICIAL de SUNAT ('03'), no una etiqueta legible
-- ('EMPLEADO'): el archivo plano del PLAME y del T-Registro exige el código exacto,
-- y guardar la etiqueta obliga a un mapeo manual en cada exportación.
--
-- Ojo: `id_regimen` (MTPE) y `cod_regimen_laboral_sunat` (Tabla 33) NO son lo mismo
-- y conviven. La T33 dice que el trabajador está en el D.Leg. 728 — eso se declara.
-- `id_regimen` dice si es MYPE y cuánta CTS le toca — eso se calcula. SUNAT no lo sabe.
CREATE TABLE `planilla_trabajador` (
  `id_trabajador` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int NOT NULL,

  -- Identificación
  `cod_tipo_documento` varchar(10) NOT NULL DEFAULT '01' COMMENT 'Tabla 3: 01 DNI, 04 C.E., 07 pasaporte',
  `numero_documento` varchar(15) NOT NULL,
  `apellido_paterno` varchar(60) NOT NULL,
  `apellido_materno` varchar(60) DEFAULT NULL,
  `nombres` varchar(80) NOT NULL,
  `fecha_nacimiento` date DEFAULT NULL,
  `sexo` enum('M','F') DEFAULT NULL,
  `cod_nacionalidad` varchar(10) DEFAULT NULL COMMENT 'Tabla 4',
  `cod_ubigeo` varchar(10) DEFAULT NULL COMMENT 'Tabla 28 — UBIGEO RENIEC, NO INEI (ver nota del paso 1)',
  `direccion` varchar(255) DEFAULT NULL,
  `email` varchar(120) DEFAULT NULL,
  `telefono` varchar(30) DEFAULT NULL,

  -- Situación laboral
  `id_regimen` int NOT NULL COMMENT 'Régimen de CÁLCULO (MTPE): general / pequeña / micro',
  `cod_regimen_laboral_sunat` varchar(10) NOT NULL DEFAULT '01' COMMENT 'Tabla 33, lo que se DECLARA (01 = privado general D.Leg. 728)',
  `cod_tipo_trabajador` varchar(10) DEFAULT NULL COMMENT 'Tabla 8',
  `cod_categoria_ocupacional` varchar(10) DEFAULT NULL COMMENT 'Tabla 24: 01 ejecutivo, 02 obrero, 03 empleado',
  `cod_tipo_contrato` varchar(10) NOT NULL DEFAULT '1' COMMENT 'Tabla 12: 1 plazo indeterminado, 2 tiempo parcial',
  `cod_ocupacion` varchar(10) DEFAULT NULL COMMENT 'Tabla 30 (sector privado)',
  `cod_periodicidad` varchar(10) NOT NULL DEFAULT '01' COMMENT 'Tabla 13: 01 mensual',
  `cod_situacion` varchar(10) NOT NULL DEFAULT '01' COMMENT 'Tabla 15: 01 activo, 00 baja, 03 suspensión perfecta',
  `cod_motivo_fin_periodo` varchar(10) DEFAULT NULL COMMENT 'Tabla 17, al cesar',
  `cargo` varchar(120) DEFAULT NULL,
  `area` varchar(120) DEFAULT NULL,
  `fecha_ingreso` date NOT NULL,
  `fecha_cese` date DEFAULT NULL,

  -- Condiciones que cambian el cálculo
  `jornada_maxima` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Sujeto a jornada máxima: si no, no genera horas extras',
  `sujeto_fiscalizacion` tinyint(1) NOT NULL DEFAULT 1,
  `discapacidad` tinyint(1) NOT NULL DEFAULT 0,
  `sindicalizado` tinyint(1) NOT NULL DEFAULT 0,
  `tiene_hijos_menores` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Gatilla la asignación familiar (10% de la RMV, Ley 25129)',

  -- Previsional y salud
  `regimen_pensionario` enum('ONP','AFP','SIN_REGIMEN') NOT NULL DEFAULT 'ONP',
  `cod_regimen_pensionario_sunat` varchar(10) DEFAULT NULL COMMENT 'Tabla 11: 02 = ONP D.L. 19990',
  `id_afp` int DEFAULT NULL,
  `cuspp` varchar(20) DEFAULT NULL COMMENT 'Código único del afiliado al SPP',
  `tipo_comision_afp` enum('FLUJO','MIXTA') DEFAULT NULL,
  `fecha_afiliacion_afp` date DEFAULT NULL,
  `cod_regimen_salud` varchar(10) DEFAULT NULL COMMENT 'Tabla 32. Si es NULL, hereda el de la empresa',
  `afecto_sctr` tinyint(1) NOT NULL DEFAULT 0,
  `essalud_vida` tinyint(1) NOT NULL DEFAULT 0,

  -- Pago
  `id_banco_sueldo` int DEFAULT NULL,
  `cuenta_sueldo` varchar(30) DEFAULT NULL,
  `cci_sueldo` varchar(25) DEFAULT NULL,
  `id_banco_cts` int DEFAULT NULL,
  `cuenta_cts` varchar(30) DEFAULT NULL,
  `cci_cts` varchar(25) DEFAULT NULL,

  `observaciones` text DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_trabajador`),
  UNIQUE KEY `uk_planilla_trabajador_doc` (`id_empresa`,`numero_documento`),
  KEY `ix_planilla_trabajador_empresa` (`id_empresa`,`cod_situacion`,`estado_registro`),
  KEY `ix_planilla_trabajador_busqueda` (`apellido_paterno`,`apellido_materno`,`nombres`),
  KEY `fk_planilla_trabajador_regimen` (`id_regimen`),
  KEY `fk_planilla_trabajador_afp` (`id_afp`),
  KEY `fk_planilla_trabajador_banco_sueldo` (`id_banco_sueldo`),
  KEY `fk_planilla_trabajador_banco_cts` (`id_banco_cts`),
  KEY `fk_planilla_trabajador_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_trabajador_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_trabajador_regimen` FOREIGN KEY (`id_regimen`) REFERENCES `planilla_regimen_laboral` (`id_regimen`),
  CONSTRAINT `fk_planilla_trabajador_afp` FOREIGN KEY (`id_afp`) REFERENCES `planilla_afp` (`id_afp`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_trabajador_banco_sueldo` FOREIGN KEY (`id_banco_sueldo`) REFERENCES `planilla_banco` (`id_banco`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_trabajador_banco_cts` FOREIGN KEY (`id_banco_cts`) REFERENCES `planilla_banco` (`id_banco`) ON DELETE SET NULL,
  CONSTRAINT `fk_planilla_trabajador_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Padrón de trabajadores por empresa cliente.';


-- ------------------------------------------------------------------------------
-- planilla_trabajador_remuneracion — historial de sueldos
-- ------------------------------------------------------------------------------
-- El sueldo NO va como columna de planilla_trabajador: cambia, y tanto el cálculo de
-- promedios (CTS y gratificación miran el semestre) como la auditoría necesitan saber
-- cuánto ganaba en cada momento. Guardarlo como columna borraría esa historia en
-- cada aumento.
CREATE TABLE `planilla_trabajador_remuneracion` (
  `id_remuneracion` int NOT NULL AUTO_INCREMENT,
  `id_trabajador` int NOT NULL,
  `vigencia_desde` date NOT NULL,
  `sueldo_basico` decimal(12,2) NOT NULL,
  `moneda` enum('PEN','USD') NOT NULL DEFAULT 'PEN',
  `motivo` enum('INGRESO','AUMENTO','CAMBIO_CARGO','REDUCCION','AJUSTE') NOT NULL DEFAULT 'INGRESO',
  `observacion` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_remuneracion`),
  UNIQUE KEY `uk_planilla_remuneracion_vigencia` (`id_trabajador`,`vigencia_desde`),
  KEY `ix_planilla_remuneracion_busqueda` (`id_trabajador`,`vigencia_desde`),
  KEY `fk_planilla_remuneracion_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_remuneracion_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_remuneracion_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Historial de sueldos básicos por trabajador, con vigencia por fecha.';


-- ------------------------------------------------------------------------------
-- planilla_trabajador_concepto_fijo — lo que se repite todos los meses
-- ------------------------------------------------------------------------------
-- Bonificación fija, movilidad, un préstamo en cuotas, una retención judicial. Sin
-- esto habría que volver a teclearlos cada mes en la planilla, que es justo lo que
-- el Excel obliga a hacer.
CREATE TABLE `planilla_trabajador_concepto_fijo` (
  `id_concepto_fijo` int NOT NULL AUTO_INCREMENT,
  `id_trabajador` int NOT NULL,
  `id_concepto` int NOT NULL,
  `monto` decimal(12,2) DEFAULT NULL COMMENT 'Monto fijo mensual. Excluyente con porcentaje',
  `porcentaje` decimal(7,4) DEFAULT NULL COMMENT '% sobre el básico. Excluyente con monto',
  `vigencia_desde` date NOT NULL,
  `vigencia_hasta` date DEFAULT NULL COMMENT 'NULL = hasta nuevo aviso',

  -- Para descuentos en cuotas (préstamos, adelantos fraccionados)
  `numero_cuotas` smallint DEFAULT NULL,
  `cuotas_pagadas` smallint NOT NULL DEFAULT 0,
  `saldo_pendiente` decimal(12,2) DEFAULT NULL COMMENT 'Se descuenta solo hasta agotarlo, aunque queden cuotas',

  `observacion` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_concepto_fijo`),
  KEY `ix_planilla_concepto_fijo_busqueda` (`id_trabajador`,`vigencia_desde`,`vigencia_hasta`),
  KEY `fk_planilla_concepto_fijo_concepto` (`id_concepto`),
  KEY `fk_planilla_concepto_fijo_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_concepto_fijo_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_concepto_fijo_concepto` FOREIGN KEY (`id_concepto`) REFERENCES `planilla_concepto` (`id_concepto`),
  CONSTRAINT `fk_planilla_concepto_fijo_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Conceptos recurrentes por trabajador (bonificaciones fijas, préstamos en cuotas, retenciones).';


-- ------------------------------------------------------------------------------
-- Permisos nuevos del módulo PLANILLA (paso 3)
-- ------------------------------------------------------------------------------
SET @id_modulo_planilla = (SELECT id_modulo FROM sis_modulo WHERE nombre = 'PLANILLA');

INSERT INTO `sis_accion` (`id_modulo`, `codigo_accion`, `descripcion`, `tipo_operacion`, `estado_registro`) VALUES
(@id_modulo_planilla, 'ver_trabajador', 'Ver el padrón de trabajadores de las empresas cliente', 'READ', 'ACTIVO'),
(@id_modulo_planilla, 'crear_trabajador', 'Registrar un trabajador nuevo', 'CREATE', 'ACTIVO'),
(@id_modulo_planilla, 'editar_trabajador', 'Editar los datos de un trabajador', 'UPDATE', 'ACTIVO'),
(@id_modulo_planilla, 'eliminar_trabajador', 'Dar de baja a un trabajador del padrón', 'DELETE', 'ACTIVO'),
(@id_modulo_planilla, 'ver_remuneracion', 'Ver el sueldo y su historial (dato sensible)', 'READ', 'ACTIVO'),
(@id_modulo_planilla, 'editar_remuneracion', 'Registrar o corregir el sueldo de un trabajador', 'UPDATE', 'ACTIVO'),
(@id_modulo_planilla, 'editar_config_empresa_planilla', 'Editar la configuración laboral de una empresa (seguro, SCTR, SENATI, jornada)', 'UPDATE', 'ACTIVO');

INSERT INTO `sis_permiso` (`id_rol`, `id_accion`, `estado_registro`)
SELECT 1, id_accion, 'ACTIVO' FROM sis_accion
WHERE id_modulo = @id_modulo_planilla
  AND codigo_accion IN ('ver_trabajador','crear_trabajador','editar_trabajador','eliminar_trabajador',
                        'ver_remuneracion','editar_remuneracion','editar_config_empresa_planilla');


-- ------------------------------------------------------------------------------
-- Config por defecto para las empresas que ya existen
-- ------------------------------------------------------------------------------
-- Sin esto, cada empresa quedaría sin configuración laboral y el motor no sabría
-- qué jornada ni qué régimen de salud usar. Se siembra con lo estándar (EsSalud
-- regular, jornada de 8 horas, mes de 30 días) y el estudio ajusta por empresa.
INSERT INTO `planilla_empresa_config`
 (`id_empresa`, `id_regimen_default`, `cod_regimen_salud`, `horas_jornada`, `dias_mes`, `id_usuario_crea`)
SELECT e.id_empresa,
       (SELECT id_regimen FROM planilla_regimen_laboral
        WHERE codigo = CASE WHEN e.regimen_tributario = 'MYPE' THEN 'PEQUENA_EMPRESA' ELSE 'REGIMEN_GENERAL' END
        LIMIT 1),
       '00', 8.00, 30, 1
FROM `empresa` e
WHERE e.estado_registro = 'ACTIVO'
ON DUPLICATE KEY UPDATE `id_empresa` = VALUES(`id_empresa`);


-- ==============================================================================
-- 5. MÓDULO PLANILLA — Paso 4: planilla mensual
-- ==============================================================================
-- Es la ficha "Planilla mensual" del Excel, más las de "Entrada de datos" y "Tareo"
-- que la alimentan.
--
-- La idea que ordena todo esto: SEPARAR EL INPUT DEL RESULTADO.
--   planilla_entrada_dato / planilla_tareo  = lo que se carga  (sobrevive al recálculo)
--   planilla_detalle / planilla_detalle_concepto = lo que se calcula (se rehace entero)
-- Es literalmente el botón "pasar a planilla" del Excel, y permite recalcular N veces
-- sin volver a teclear nada.
-- ==============================================================================


-- ------------------------------------------------------------------------------
-- planilla_planilla — la corrida del mes
-- ------------------------------------------------------------------------------
CREATE TABLE `planilla_planilla` (
  `id_planilla` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int NOT NULL,
  `anio` smallint NOT NULL,
  `mes` tinyint NOT NULL,
  `tipo` enum('MENSUAL','ADICIONAL') NOT NULL DEFAULT 'MENSUAL',

  `estado` enum('BORRADOR','CALCULADA','CERRADA','ANULADA') NOT NULL DEFAULT 'BORRADOR'
    COMMENT 'BORRADOR: se puede recalcular. CERRADA: congelada, ya se declaró',

  `fecha_calculo` datetime DEFAULT NULL,
  `fecha_cierre` datetime DEFAULT NULL,
  `fecha_pago_quincena` date DEFAULT NULL,
  `fecha_pago_mes` date DEFAULT NULL,

  -- Snapshot de la configuración usada. Si mañana cambia la jornada de la empresa,
  -- la planilla de marzo tiene que seguir explicándose con la jornada de marzo.
  `snap_dias_mes` smallint NOT NULL DEFAULT 30,
  `snap_horas_jornada` decimal(4,2) NOT NULL DEFAULT 8.00,
  `snap_rmv` decimal(12,2) DEFAULT NULL,
  `snap_uit` decimal(12,2) DEFAULT NULL,

  `total_ingresos` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_descuentos` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_aportes` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_neto` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_trabajadores` int NOT NULL DEFAULT 0,

  `observaciones` text DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_planilla`),
  UNIQUE KEY `uk_planilla_periodo` (`id_empresa`,`anio`,`mes`,`tipo`),
  KEY `ix_planilla_busqueda` (`id_empresa`,`anio`,`mes`,`estado`),
  KEY `fk_planilla_planilla_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_planilla_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_planilla_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Cabecera de la corrida mensual por empresa y periodo.';


-- ------------------------------------------------------------------------------
-- planilla_entrada_dato — la ficha "Entrada de datos" completa, en UNA tabla
-- ------------------------------------------------------------------------------
-- El Excel tiene ocho cuadros distintos (adelanto de quincena, ingresos, descuentos,
-- vacaciones, días no laborados, horas extras/feriados, renta de 5ta, Vida Ley).
-- Todos tienen la MISMA forma: trabajador + concepto + cantidad/monto. Ocho tablas
-- serían ocho CRUDs idénticos que mantener; el campo `origen` conserva de qué cuadro
-- vino para poder reproducir las pestañas en la UI.
CREATE TABLE `planilla_entrada_dato` (
  `id_entrada` int NOT NULL AUTO_INCREMENT,
  `id_planilla` int NOT NULL,
  `id_trabajador` int NOT NULL,
  `id_concepto` int DEFAULT NULL COMMENT 'NULL cuando la fila es solo días/horas y el motor decide el concepto',

  `origen` enum('ADELANTO_QUINCENA','INGRESO','DESCUENTO','VACACIONES','DIAS_NO_LABORADOS',
                'HORAS_EXTRAS','FERIADOS','RENTA_QUINTA','VIDA_LEY_SCTR','TAREO','IMPORTACION')
    NOT NULL DEFAULT 'INGRESO',

  `cantidad` decimal(10,2) DEFAULT NULL COMMENT 'Horas o días, según el concepto',
  `porcentaje` decimal(7,4) DEFAULT NULL,
  `monto` decimal(12,2) DEFAULT NULL,

  `observacion` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_entrada`),
  KEY `ix_planilla_entrada_busqueda` (`id_planilla`,`id_trabajador`,`origen`),
  KEY `fk_planilla_entrada_trabajador` (`id_trabajador`),
  KEY `fk_planilla_entrada_concepto` (`id_concepto`),
  KEY `fk_planilla_entrada_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_entrada_planilla` FOREIGN KEY (`id_planilla`) REFERENCES `planilla_planilla` (`id_planilla`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_entrada_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_entrada_concepto` FOREIGN KEY (`id_concepto`) REFERENCES `planilla_concepto` (`id_concepto`),
  CONSTRAINT `fk_planilla_entrada_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Datos cargados a mano que alimentan el cálculo (ficha "Entrada de datos" del Excel).';


-- ------------------------------------------------------------------------------
-- planilla_tareo — la ficha "Tareo": un registro por trabajador y DÍA
-- ------------------------------------------------------------------------------
-- A nivel día y no agregado, porque es lo que pide la ficha y lo que exige el
-- registro de control de asistencia ante SUNAFIL. El botón "Calcular datos" agrupa
-- esta tabla por marca y escribe el resumen en planilla_entrada_dato.
CREATE TABLE `planilla_tareo` (
  `id_tareo` int NOT NULL AUTO_INCREMENT,
  `id_planilla` int NOT NULL,
  `id_trabajador` int NOT NULL,
  `dia` tinyint NOT NULL COMMENT '1..31',
  `fecha` date NOT NULL,
  `id_marca` int NOT NULL,

  `horas_trabajadas` decimal(5,2) DEFAULT NULL,
  `horas_extras_25` decimal(5,2) NOT NULL DEFAULT 0.00,
  `horas_extras_35` decimal(5,2) NOT NULL DEFAULT 0.00,
  `minutos_tardanza` smallint NOT NULL DEFAULT 0,

  `observacion` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_tareo`),
  UNIQUE KEY `uk_planilla_tareo_dia` (`id_planilla`,`id_trabajador`,`dia`),
  KEY `ix_planilla_tareo_busqueda` (`id_planilla`,`id_trabajador`),
  KEY `fk_planilla_tareo_marca` (`id_marca`),
  KEY `fk_planilla_tareo_trabajador` (`id_trabajador`),
  KEY `fk_planilla_tareo_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_tareo_planilla` FOREIGN KEY (`id_planilla`) REFERENCES `planilla_planilla` (`id_planilla`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_tareo_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_tareo_marca` FOREIGN KEY (`id_marca`) REFERENCES `planilla_tareo_marca` (`id_marca`),
  CONSTRAINT `fk_planilla_tareo_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Tareo diario por trabajador (ficha "Tareo" del Excel).';


-- ------------------------------------------------------------------------------
-- planilla_detalle — una fila por trabajador en la planilla, con SNAPSHOT
-- ------------------------------------------------------------------------------
-- Los `snap_*` congelan todo lo que el cálculo usó. Si el trabajador cambia de AFP
-- en abril, la planilla de marzo debe seguir mostrando —y pudiendo re-explicar— el
-- descuento con la AFP y las tasas de marzo. Sin snapshot, reabrir una planilla vieja
-- daría números distintos a los que se declararon.
CREATE TABLE `planilla_detalle` (
  `id_detalle` int NOT NULL AUTO_INCREMENT,
  `id_planilla` int NOT NULL,
  `id_trabajador` int NOT NULL,

  `snap_id_regimen` int NOT NULL,
  `snap_factor_cts` decimal(4,2) NOT NULL DEFAULT 1.00,
  `snap_factor_gratificacion` decimal(4,2) NOT NULL DEFAULT 1.00,
  `snap_sueldo_basico` decimal(12,2) NOT NULL,
  `snap_regimen_pensionario` enum('ONP','AFP','SIN_REGIMEN') NOT NULL,
  `snap_id_afp` int DEFAULT NULL,
  `snap_id_afp_tasa` int DEFAULT NULL COMMENT 'Qué fila de tasas se usó: permite auditar el descuento años después',
  `snap_tipo_comision_afp` enum('FLUJO','MIXTA') DEFAULT NULL,

  `dias_laborados` decimal(5,2) NOT NULL DEFAULT 0.00,
  `dias_no_laborados` decimal(5,2) NOT NULL DEFAULT 0.00,
  `dias_subsidiados` decimal(5,2) NOT NULL DEFAULT 0.00,
  `dias_faltas` decimal(5,2) NOT NULL DEFAULT 0.00,
  `dias_vacaciones` decimal(5,2) NOT NULL DEFAULT 0.00,
  `horas_extras_25` decimal(6,2) NOT NULL DEFAULT 0.00,
  `horas_extras_35` decimal(6,2) NOT NULL DEFAULT 0.00,

  `remuneracion_asegurable` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Base de AFP/ONP/EsSalud: solo conceptos remunerativos',
  `base_renta_quinta` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_ingresos` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_descuentos` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_aportes_empleador` decimal(14,2) NOT NULL DEFAULT 0.00,
  `adelanto_quincena` decimal(14,2) NOT NULL DEFAULT 0.00,
  `neto_pagar` decimal(14,2) NOT NULL DEFAULT 0.00,

  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  PRIMARY KEY (`id_detalle`),
  UNIQUE KEY `uk_planilla_detalle` (`id_planilla`,`id_trabajador`),
  KEY `fk_planilla_detalle_trabajador` (`id_trabajador`),
  KEY `fk_planilla_detalle_regimen` (`snap_id_regimen`),
  CONSTRAINT `fk_planilla_detalle_planilla` FOREIGN KEY (`id_planilla`) REFERENCES `planilla_planilla` (`id_planilla`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_detalle_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`),
  CONSTRAINT `fk_planilla_detalle_regimen` FOREIGN KEY (`snap_id_regimen`) REFERENCES `planilla_regimen_laboral` (`id_regimen`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Resultado por trabajador, con snapshot de todo lo que el cálculo usó.';


-- ------------------------------------------------------------------------------
-- planilla_detalle_concepto — el desglose línea por línea
-- ------------------------------------------------------------------------------
-- Es lo que hace la planilla auditable, imprimible en boleta y exportable al PLAME.
-- Guardar solo los totales haría imposible responder "¿de dónde sale este monto?".
CREATE TABLE `planilla_detalle_concepto` (
  `id_detalle_concepto` int NOT NULL AUTO_INCREMENT,
  `id_detalle` int NOT NULL,
  `id_concepto` int NOT NULL,
  `codigo_plame` char(4) NOT NULL COMMENT 'Copiado del concepto: la boleta y el PLAME lo necesitan aunque el catálogo cambie',
  `nombre_concepto` varchar(255) NOT NULL,
  `tipo` enum('INGRESO','DESCUENTO','APORTE_EMPLEADOR') NOT NULL,

  `cantidad` decimal(10,2) DEFAULT NULL COMMENT 'Horas o días que originaron el monto',
  `base_calculo` decimal(14,2) DEFAULT NULL,
  `porcentaje_aplicado` decimal(7,4) DEFAULT NULL,
  `monto` decimal(14,2) NOT NULL DEFAULT 0.00,

  `orden_impresion` int NOT NULL DEFAULT 0,
  `es_manual` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = vino de "Entrada de datos", 0 = lo calculó el motor',
  `observacion` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_detalle_concepto`),
  KEY `ix_planilla_detalle_concepto` (`id_detalle`,`tipo`,`orden_impresion`),
  KEY `fk_planilla_detalle_concepto_concepto` (`id_concepto`),
  CONSTRAINT `fk_planilla_detalle_concepto_detalle` FOREIGN KEY (`id_detalle`) REFERENCES `planilla_detalle` (`id_detalle`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_detalle_concepto_concepto` FOREIGN KEY (`id_concepto`) REFERENCES `planilla_concepto` (`id_concepto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Desglose de conceptos por trabajador: la boleta y el archivo PLAME salen de acá.';


-- ------------------------------------------------------------------------------
-- planilla_provision — la sección "Provisiones" del Excel
-- ------------------------------------------------------------------------------
-- Proyección mensual de lo que la empresa va a tener que pagar por CTS, vacaciones y
-- gratificación. No es un descuento ni un pago: es un devengo contable, y por eso
-- vive aparte del desglose de la boleta.
CREATE TABLE `planilla_provision` (
  `id_provision` int NOT NULL AUTO_INCREMENT,
  `id_planilla` int NOT NULL,
  `id_trabajador` int NOT NULL,
  `tipo` enum('CTS','VACACIONES','GRATIFICACION') NOT NULL,

  `base_calculo` decimal(14,2) NOT NULL DEFAULT 0.00,
  `factor_mensual` decimal(8,6) NOT NULL DEFAULT 0.000000 COMMENT 'CTS y vacaciones 1/12, gratificación 1/6, por el factor del régimen',
  `monto_mes` decimal(14,2) NOT NULL DEFAULT 0.00,

  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  PRIMARY KEY (`id_provision`),
  UNIQUE KEY `uk_planilla_provision` (`id_planilla`,`id_trabajador`,`tipo`),
  KEY `fk_planilla_provision_trabajador` (`id_trabajador`),
  CONSTRAINT `fk_planilla_provision_planilla` FOREIGN KEY (`id_planilla`) REFERENCES `planilla_planilla` (`id_planilla`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_provision_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Provisión mensual de CTS, vacaciones y gratificación (devengo contable).';


-- ------------------------------------------------------------------------------
-- Permisos nuevos del módulo PLANILLA (paso 4)
-- ------------------------------------------------------------------------------
SET @id_modulo_planilla = (SELECT id_modulo FROM sis_modulo WHERE nombre = 'PLANILLA');

INSERT INTO `sis_accion` (`id_modulo`, `codigo_accion`, `descripcion`, `tipo_operacion`, `estado_registro`) VALUES
(@id_modulo_planilla, 'ver_planilla', 'Ver las planillas mensuales y su detalle', 'READ', 'ACTIVO'),
(@id_modulo_planilla, 'crear_planilla', 'Abrir la planilla de un periodo', 'CREATE', 'ACTIVO'),
(@id_modulo_planilla, 'editar_entrada_datos', 'Cargar ingresos, descuentos, horas extras y adelantos', 'UPDATE', 'ACTIVO'),
(@id_modulo_planilla, 'editar_tareo', 'Llenar el tareo diario', 'UPDATE', 'ACTIVO'),
(@id_modulo_planilla, 'calcular_planilla', 'Procesar el cálculo de la planilla', 'SPECIAL', 'ACTIVO'),
(@id_modulo_planilla, 'cerrar_planilla', 'Cerrar la planilla (queda congelada, ya no se recalcula)', 'SPECIAL', 'ACTIVO'),
(@id_modulo_planilla, 'anular_planilla', 'Anular una planilla cerrada', 'DELETE', 'ACTIVO'),
(@id_modulo_planilla, 'generar_boleta', 'Generar e imprimir las boletas de pago', 'READ', 'ACTIVO');

INSERT INTO `sis_permiso` (`id_rol`, `id_accion`, `estado_registro`)
SELECT 1, id_accion, 'ACTIVO' FROM sis_accion
WHERE id_modulo = @id_modulo_planilla
  AND codigo_accion IN ('ver_planilla','crear_planilla','editar_entrada_datos','editar_tareo',
                        'calcular_planilla','cerrar_planilla','anular_planilla','generar_boleta');


-- ==============================================================================
-- 6. MÓDULO PLANILLA — Paso 5: beneficios sociales (CTS, gratificaciones, liquidación)
-- ==============================================================================
-- Es la ficha "Beneficios sociales" del Excel y el título del video.
--
-- Una sola cabecera para los cuatro cálculos (CTS, gratificación, vacaciones,
-- liquidación) porque comparten el 90%: todos parten de la misma remuneración
-- computable y del mismo conteo de tiempo de servicios. Separarlos en cuatro tablas
-- obligaría a duplicar ese motor cuatro veces, que es exactamente donde aparecen las
-- diferencias de centavos entre un cálculo y otro.
-- ==============================================================================


-- ------------------------------------------------------------------------------
-- planilla_beneficio — la corrida del beneficio
-- ------------------------------------------------------------------------------
CREATE TABLE `planilla_beneficio` (
  `id_beneficio` int NOT NULL AUTO_INCREMENT,
  `id_empresa` int NOT NULL,
  `tipo` enum('CTS','GRATIFICACION','VACACIONES','LIQUIDACION') NOT NULL,

  -- El semestre que se está liquidando. CTS: nov→abr o may→oct.
  -- Gratificación: ene→jun (se paga en julio) o jul→dic (se paga en diciembre).
  `periodo_desde` date NOT NULL,
  `periodo_hasta` date NOT NULL,
  `anio` smallint NOT NULL,
  `semestre` tinyint DEFAULT NULL COMMENT '1 o 2. NULL en liquidaciones, que no siguen el semestre',

  `fecha_pago_legal` date DEFAULT NULL COMMENT 'Hasta cuándo se puede pagar sin generar intereses',
  `fecha_pago_real` date DEFAULT NULL COMMENT 'Cuándo se pagó. La diferencia con la legal gatilla el interés',
  `tea_interes` decimal(7,4) NOT NULL DEFAULT 0.0000 COMMENT 'Tasa efectiva anual para el interés por mora',

  `estado` enum('BORRADOR','CALCULADO','CERRADO','ANULADO') NOT NULL DEFAULT 'BORRADOR',
  `fecha_calculo` datetime DEFAULT NULL,

  -- Snapshot de los parámetros usados, igual que en la planilla mensual.
  `snap_rmv` decimal(12,2) DEFAULT NULL,
  `snap_pct_bonif_essalud` decimal(7,4) DEFAULT NULL COMMENT 'Bonificación extraordinaria Ley 30334: 9% EsSalud',
  `snap_pct_bonif_eps` decimal(7,4) DEFAULT NULL COMMENT '6.75% si el trabajador está en EPS',

  `total_monto` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_bonificacion` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_interes` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_pagar` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_trabajadores` int NOT NULL DEFAULT 0,

  `observaciones` text DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` int NOT NULL,
  `id_usuario_mod` int DEFAULT NULL,
  PRIMARY KEY (`id_beneficio`),
  UNIQUE KEY `uk_planilla_beneficio_periodo` (`id_empresa`,`tipo`,`periodo_desde`,`periodo_hasta`),
  KEY `ix_planilla_beneficio_busqueda` (`id_empresa`,`tipo`,`anio`,`estado`),
  KEY `fk_planilla_beneficio_usuario` (`id_usuario_crea`),
  CONSTRAINT `fk_planilla_beneficio_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_beneficio_usuario` FOREIGN KEY (`id_usuario_crea`) REFERENCES `sis_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Cabecera del cálculo de CTS, gratificaciones, vacaciones y liquidaciones.';


-- ------------------------------------------------------------------------------
-- planilla_beneficio_detalle — el cálculo por trabajador, DESGLOSADO
-- ------------------------------------------------------------------------------
-- La remuneración computable va abierta en sus componentes y no como un solo número.
-- En el Excel eso es una celda con una fórmula ilegible; acá cada parte queda visible.
-- Es lo que hay que sustentar ante SUNAFIL en una fiscalización, y lo que el contador
-- necesita para explicarle al cliente de dónde sale la cifra.
CREATE TABLE `planilla_beneficio_detalle` (
  `id_beneficio_detalle` int NOT NULL AUTO_INCREMENT,
  `id_beneficio` int NOT NULL,
  `id_trabajador` int NOT NULL,

  `sub_tipo` enum('CTS','GRATIFICACION','VACACIONES','INDEMNIZACION') DEFAULT NULL
    COMMENT 'Solo en LIQUIDACION, que junta varios beneficios en una sola corrida',

  `snap_id_regimen` int NOT NULL,
  `snap_factor_regimen` decimal(4,2) NOT NULL DEFAULT 1.00 COMMENT '1.00 general / 0.50 pequeña / 0.00 micro',

  -- Remuneración computable, componente por componente.
  `rc_basico` decimal(12,2) NOT NULL DEFAULT 0.00,
  `rc_asignacion_familiar` decimal(12,2) NOT NULL DEFAULT 0.00,
  `rc_promedio_horas_extras` decimal(12,2) NOT NULL DEFAULT 0.00
    COMMENT 'Solo si se percibieron 3+ meses en el semestre; se promedia sobre 6',
  `rc_promedio_comisiones` decimal(12,2) NOT NULL DEFAULT 0.00,
  `rc_promedio_bonificaciones` decimal(12,2) NOT NULL DEFAULT 0.00,
  `rc_sexto_gratificacion` decimal(12,2) NOT NULL DEFAULT 0.00
    COMMENT 'Solo CTS: 1/6 de la gratificación del semestre anterior (D. Leg. 650)',
  `remuneracion_computable` decimal(12,2) NOT NULL DEFAULT 0.00,

  -- Tiempo de servicios del periodo.
  `fecha_inicio_computo` date NOT NULL,
  `fecha_fin_computo` date NOT NULL,
  `meses_computables` tinyint NOT NULL DEFAULT 0,
  `dias_computables` smallint NOT NULL DEFAULT 0,
  `dias_no_computables` smallint NOT NULL DEFAULT 0
    COMMENT 'Faltas injustificadas, licencias sin goce y suspensiones perfectas: no suman',

  -- Resultado.
  `monto_base` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Antes de aplicar el factor del régimen',
  `monto_beneficio` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Ya con el factor del régimen aplicado',
  `pct_bonificacion_extraordinaria` decimal(7,4) NOT NULL DEFAULT 0.0000,
  `monto_bonificacion` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT 'Solo gratificación: Ley 30334',
  `dias_mora` smallint NOT NULL DEFAULT 0,
  `monto_interes` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_pagar` decimal(14,2) NOT NULL DEFAULT 0.00,

  `id_banco_destino` int DEFAULT NULL COMMENT 'Solo CTS: va a la cuenta CTS, no a la de haberes',
  `cci_destino` varchar(25) DEFAULT NULL,
  `observacion` varchar(255) DEFAULT NULL,
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  PRIMARY KEY (`id_beneficio_detalle`),
  UNIQUE KEY `uk_planilla_beneficio_detalle` (`id_beneficio`,`id_trabajador`,`sub_tipo`),
  KEY `fk_planilla_beneficio_detalle_trabajador` (`id_trabajador`),
  KEY `fk_planilla_beneficio_detalle_regimen` (`snap_id_regimen`),
  KEY `fk_planilla_beneficio_detalle_banco` (`id_banco_destino`),
  CONSTRAINT `fk_planilla_beneficio_detalle_beneficio` FOREIGN KEY (`id_beneficio`) REFERENCES `planilla_beneficio` (`id_beneficio`) ON DELETE CASCADE,
  CONSTRAINT `fk_planilla_beneficio_detalle_trabajador` FOREIGN KEY (`id_trabajador`) REFERENCES `planilla_trabajador` (`id_trabajador`),
  CONSTRAINT `fk_planilla_beneficio_detalle_regimen` FOREIGN KEY (`snap_id_regimen`) REFERENCES `planilla_regimen_laboral` (`id_regimen`),
  CONSTRAINT `fk_planilla_beneficio_detalle_banco` FOREIGN KEY (`id_banco_destino`) REFERENCES `planilla_banco` (`id_banco`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='MÓDULO: Planilla. Cálculo de beneficios por trabajador, con la remuneración computable abierta en sus componentes.';


-- ------------------------------------------------------------------------------
-- Permisos nuevos del módulo PLANILLA (paso 5)
-- ------------------------------------------------------------------------------
SET @id_modulo_planilla = (SELECT id_modulo FROM sis_modulo WHERE nombre = 'PLANILLA');

INSERT INTO `sis_accion` (`id_modulo`, `codigo_accion`, `descripcion`, `tipo_operacion`, `estado_registro`) VALUES
(@id_modulo_planilla, 'ver_beneficio', 'Ver los cálculos de CTS, gratificaciones y liquidaciones', 'READ', 'ACTIVO'),
(@id_modulo_planilla, 'calcular_beneficio', 'Procesar el cálculo de un beneficio social', 'SPECIAL', 'ACTIVO'),
(@id_modulo_planilla, 'cerrar_beneficio', 'Cerrar el cálculo de un beneficio (queda congelado)', 'SPECIAL', 'ACTIVO');

INSERT INTO `sis_permiso` (`id_rol`, `id_accion`, `estado_registro`)
SELECT 1, id_accion, 'ACTIVO' FROM sis_accion
WHERE id_modulo = @id_modulo_planilla
  AND codigo_accion IN ('ver_beneficio','calcular_beneficio','cerrar_beneficio');


-- ------------------------------------------------------------------------------
-- Guía de navegación: T-REGISTRO (padrón de trabajadores)
-- ==============================================================================
--  CATÁLOGO DE ERRORES CONOCIDOS DE SUNAT
-- ==============================================================================
-- El código la consultaba desde el 27/08/2026 (trabajadores.service.ts,
-- anotarErroresConocidos) pero la tabla no existía: cada corrida del T-Registro
-- terminaba con "Table 'sunat_error_conocido' doesn't exist" al pie del
-- diagnóstico. La consulta está dentro de un try, así que nunca rompió nada —
-- solo ensuciaba.
--
-- PARA QUÉ SIRVE: el diagnóstico del scraping es largo y quien lo lee no siempre
-- distingue "SUNAT está caído" de "nos equivocamos de selector". Este catálogo
-- traduce: cuando un patrón coincide, se agrega una línea que dice de quién es el
-- problema, por qué pasa y si reintentar sirve — porque cada reintento gasta una
-- sesión y el WAF tolera ~8 por día.
--
-- Los patrones se guardan SIN TILDES a propósito: la comparación normaliza los dos
-- lados, y el portal escribe los acentos de forma inconsistente.
CREATE TABLE IF NOT EXISTS `sunat_error_conocido` (
  `id_error` int NOT NULL AUTO_INCREMENT COMMENT 'Llave primaria',
  `codigo` varchar(30) NOT NULL COMMENT 'Código corto para nombrarlo al hablar (ej: WAF_CORTE)',
  `patron` varchar(400) NOT NULL COMMENT 'Expresion regular que se busca en el diagnostico. SIN TILDES.',
  `titulo` varchar(200) NOT NULL COMMENT 'Qué pasó, en una línea',
  `origen` enum('SUNAT','NUESTRO','USUARIO','RED') NOT NULL DEFAULT 'SUNAT' COMMENT 'De quién es el problema',
  `causa` text NOT NULL COMMENT 'Por qué ocurre',
  `que_hacer` text NOT NULL COMMENT 'Qué hacer al respecto',
  `reintentar_sirve` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 = reintentar gasta una sesión del WAF para nada',
  `veces_visto` int NOT NULL DEFAULT '0' COMMENT 'Cuántas veces coincidió: separa lo que falla seguido de la anécdota de un día',
  `ultima_vez` datetime DEFAULT NULL COMMENT 'Última coincidencia',
  `estado_registro` enum('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  PRIMARY KEY (`id_error`),
  UNIQUE KEY `uk_codigo_error` (`codigo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='MÓDULO: Vencimientos/Planilla. Traduce los fallos del scraping de SUNAT.';

INSERT INTO `sunat_error_conocido` (`codigo`, `patron`, `titulo`, `origen`, `causa`, `que_hacer`, `reintentar_sirve`) VALUES
