-- ------------------------------------------------------------------------------
-- Esta guía es la ESPECIFICACIÓN del scraper: los pasos de acá y los selectores de
-- planilla/trabajadores/sunat-tregistro-scraping.client.ts describen el mismo
-- recorrido. Si SUNAT cambia un texto de menú, hay que corregir LOS DOS.
--
-- Estado al 01/09/2026: RECORRIDO COMPLETO VERIFICADO DE PUNTA A PUNTA. Corrida
-- real contra el RUC 20530093019: 11 trabajadores, 11 sueldos leídos. Login, menú,
-- padrón, ficha de cada persona, pestaña "Trabajador", "Monto de remuneración
-- básica inicial" y la vuelta al padrón entre ficha y ficha. Todo lo de abajo está
-- comprobado en pantalla, no supuesto.
INSERT INTO guias_sunat (codigo, nombre, pasos, estado, id_usuario_crea)
SELECT 'TREG', 'T-Registro — Padrón de Trabajadores', '', 'ACTIVO', 1
ON DUPLICATE KEY UPDATE codigo = codigo;

UPDATE guias_sunat SET nombre = 'T-Registro — Padrón de Trabajadores', pasos = '1. Entrar a https://www.sunat.gob.pe/sol.html
2. Clic en "Mis tramites y consultas" — NO en "Mis Declaraciones y Pagos".
   Ver el aviso de abajo: esta eleccion decide todo.
   (Abre una ventana nueva en e-menu.sunat.gob.pe/cl-ti-itmenucabina/MenuInternet.htm)
3. En la ventana nueva, clic en "Ingresar por RUC"
4. Llenar RUC + Usuario SOL + Clave SOL, clic en "Iniciar sesion"
5. Ya aparece el menu COMPLETO de SOL. Desde ahi:
6. Empresas
7. Mi RUC y Otros Registros
8. T-Registro
9. Registro de Trabaj., Pension., Pers. en forma...
10. Registro individual
11. Sale la pantalla "Registro de Trabajadores, Pensionistas y Otros" con la tabla
    del padron ya listada, sin buscar nada. Columnas (verificadas 01/09/2026):
      Categoria | Documento de Identidad | Apellidos y Nombres | Fec. Nac. |
      Sexo | Estado | Modificar | Eliminar
    Abajo dice "1 - N de N elementos".

    ⚠️ LAS DOS ULTIMAS COLUMNAS SON ICONOS SIN TEXTO Y LA ULTIMA BORRA. El lapiz de
    "Modificar" abre la ficha; la X roja de "Eliminar" da de baja al trabajador en
    el T-Registro del cliente. A ojo se distinguen; para el scraper no: por eso
    abre la ficha SOLO por el enlace que llama a irModificar() y, si no lo
    encuentra, se detiene en vez de probar el resto de la fila.

12. Clic en el lapiz de "Modificar" de una fila. Abre la ficha de esa persona, que
    arranca en "Datos de Identificacion" (nacionalidad, telefono, correo, estado
    civil, direccion).

13. En la seccion "Categoria" hay cuatro pestañas:
      Resumen de Prestadores | Trabajador | Pensionista | Personal en formacion laboral
    Abre en "Resumen de Prestadores", QUE NO TRAE NINGUN MONTO. Hay que entrar a
    la pestaña "Trabajador".

14. Dentro de "Trabajador", en el bloque "Datos laborales", esta el sueldo:
      "Monto de remuneracion basica inicial:"  ->  p. ej. 2000
    Es un campo de formulario, no texto suelto: hay que leer su VALOR. Y viene sin
    decimales, asi que un patron que exija ",00" no lo encuentra.
    En ese mismo bloque estan: Periodo laboral (Fecha de Inicio = fecha de ingreso),
    Tipo de trabajador, Regimen laboral, Categoria ocupacional, Ocupacion y Tipo de
    contrato. OJO con el orden: los rotulos de las tres columnas de fechas van
    TODOS JUNTOS antes de los campos, asi que "lo que sigue a Fecha de Inicio" no
    es una fecha sino el rotulo de al lado.

15. El regimen pensionario y el CUSPP NO estan ahi: viven en "Datos de Seguridad
    Social", una seccion PLEGADA mas abajo (junto con "Datos de la Situacion
    Educativa" y "Datos Tributarios"). Hay que desplegarla.

16. Salir de la ficha con "Retornar". NUNCA con "Salir": eso cierra la sesion de
    SUNAT entera y obliga a loguearse de nuevo (y el WAF cuenta cada login).

    A MANO, "Retornar" alcanza. EL SCRAPER NO LO USA como primera opcion, y esto es
    lo que mas costo del modulo entero: despues de la primera ficha no habia forma
    confiable de volver al padron. "Retornar" no respondia al clic automatico;
    retroceder en el historial movia la pagina del MENU de SOL y no la app, porque
    la ficha se abre por POST DENTRO del iframe; y volver a entrar por el menu daba
    "OK" dejando el iframe mostrando la misma ficha. Resultado: se leia UN sueldo de
    once y el resto salia vacio, sin ningun error.

    Lo que si funciona: RECARGAR EL IFRAME CON SU PROPIA URL, la de
    ol-ti-itrtpspresta/prestadores.htm?hc&token=..., que es donde se encontro el
    padron la primera vez. Es una navegacion de solo lectura y no depende de
    acertarle a ningun boton. Once de once.

17. OJO CON LOS TIEMPOS. La ficha se abre por POST dentro del iframe y tarda: si se
    lee apenas cae el clic, sale el formulario VACIO y el trabajador queda sin
    sueldo sin dar error. Por eso el scraper confirma que aparecio "Datos laborales"
    antes de leer, y reintenta. En la corrida buena, 2 de los 11 necesitaron ese
    reintento.

    Y hay que abrir UNA FICHA POR TRABAJADOR: el tiempo crece con la planilla. Once
    fichas son un par de minutos. El techo de la peticion esta en 10 minutos
    (RUTAS_LARGAS en timeout.interceptor.ts); una planilla muy grande puede pasarlo.

18. Con el resultado, volver al sistema: Planilla -> Trabajadores -> TRAER DEL
    T-REGISTRO (automatico), o IMPORTAR DE EXCEL si se prefiere a mano.

═══ EL PASO 2 ES EL QUE DECIDE TODO ═══

sol.html tiene varias puertas, y cada una deja la sesion en una APLICACION DISTINTA
del portal. No se puede saltar de una a otra despues.

  "Mis Declaraciones y Pagos"   -> cl-ti-itmenu2/MenuInternetPlataforma.htm?exe=55.1.1.1.1
      La sesion queda ENCERRADA en ese modulo. El menu lateral solo muestra su arbol
      (Declara Facil, los formularios, el 621). Las opciones del T-Registro no estan
      escondidas ahi: no existen en la pagina.

  "Mis tramites y consultas"    -> cl-ti-itmenucabina/MenuInternet.htm
      Menu COMPLETO de SOL. Aca si vive Empresas -> Mi RUC y Otros Registros ->
      T-Registro. Es la puerta correcta.

LO QUE NO FUNCIONA (probado y fallado el 27/08/2026 — no repetirlo):
  - Quitarle el "exe=" a la URL de aterrizaje. Sigue siendo la app equivocada.
  - Ir directo por URL a cl-ti-itmenu/MenuInternet.htm estando ya logueado. SUNAT
    rebota al login de api-seguridad pidiendo credenciales otra vez: la sesion NO se
    comparte entre las aplicaciones, cada una hace su propio handoff de token por
    AutenticaMenuInternet.htm y la URL pelada se lo saltea.
  - Buscar un link "Ir al inicio" para escaparse del modulo. La salida no es escapar
    del modulo equivocado: es no entrar en el.

OJO CON EL SINTOMA: el rebote al login NO da error. La pagina carga con HTTP 200 y el
scraper seguiria haciendo clics a ciegas sobre un formulario de credenciales sin
entender por que no encuentra el menu.

═══ QUE TRAE Y QUE NO TRAE ESA PANTALLA ═══

- El documento NO viene como numero pelado: la celda dice "L.E / DNI - 18191432".
  El scraper lo extrae con expresion regular, no compara la celda entera.
- La columna "Fecha" de esta pantalla es la de NACIMIENTO, no la de ingreso (se ven
  años como 1958 o 1974). El sistema la guarda aparte y NO la usa como fecha de
  ingreso: hacerlo daria trabajadores con 60 años de servicio y una CTS absurda.
- "Categoria" = TRA es trabajador. Pensionistas, prestadores de servicios y personal
  en formacion tienen otro codigo y no van al padron de planilla.
- La remuneracion basica SI esta en el T-Registro (Estructura 5, campo 16 del anexo
  de estructuras), pero NO en este listado: hay que abrir la ficha de cada
  trabajador, una por una (pasos 12 a 14). Con 11 trabajadores son 11 idas y
  vueltas dentro de la MISMA sesion — eso no gasta logins, pero si tiempo.
- Y es la remuneracion INICIAL, la del ingreso: los aumentos posteriores no estan
  en el T-Registro, viven en el PLAME declaracion por declaracion. Para el sueldo
  de HOY, el Excel del estudio es mejor fuente que esta pantalla.

═══ ESTA GUIA ES LA ESPECIFICACION DEL SCRAPER ═══

Los pasos 2 y 6 a 16 estan replicados en el bloque SELECTORES de
  planilla/trabajadores/sunat-tregistro-scraping.client.ts
Si SUNAT cambia un texto de menu, hay que corregir LOS DOS lugares. El endpoint de
scraping devuelve un "diagnostico" que lista lo que vio en pantalla (y el HTML real
de los elementos que no pudo tocar): eso permite corregir sin gastar otra sesion.

═══ RAZON SOCIAL DESACTUALIZADA ═══

El RUC 20530093019 figura en SUNAT como "A & G MK INVERSIONES E.I.R.L." y en nuestra
base como "A&G TRANPSORTES Y SERVICIOS EIRL". El RUC y la Clave SOL son correctos: lo
que esta viejo es la razon social nuestra. No es un cruce de credenciales.

═══ CUIDADO CON EL WAF ═══

SUNAT empieza a cortar conexiones tras ~8 sesiones seguidas en poco tiempo. Espaciar
los intentos. Insistir arriesga que restrinjan el acceso a la cuenta de un cliente.'
WHERE codigo = 'TREG';

-- ==============================================================================
-- 7. MÓDULO TESORERÍA — cuentas, movimientos, cobrar y pagar
-- ==============================================================================
-- Modelo adaptado de `bdgrupogalarreta` (ordenes_cobro / ordenes_pago / movimientos),
-- que ya está probado en producción, con tres cambios de fondo:
--
--   1. TODO LLEVA `id_empresa`. Acá el estudio maneja la plata de 171 empresas
--      distintas y siempre se trabaja sobre la que el usuario elige, igual que en
--      planilla. En el original había `id_empresa_que_cobra` / `id_empresa_que_paga`
--      porque era un grupo de empresas cobrándose entre sí; ese caso no aplica.
--   2. Convenciones de ESTE proyecto: `estado_registro ENUM('ACTIVO','ELIMINADO')`,
--      `id_usuario_crea`/`id_usuario_mod`, sin `created_at`/`updated_at`.
--   3. La moneda es un ENUM PEN/USD en vez de una FK a una tabla de monedas: en Perú
--      son esas dos y una tabla entera para dos filas es ceremonia sin beneficio.
--
-- Los bancos NO se duplican: se usa `planilla_banco`, que ya está cargada desde la
-- Tabla 36 de SUNAT (entidades del sistema financiero). El nombre quedó con prefijo
-- de planilla por historia, pero el catálogo es general — duplicarlo obligaría a
-- mantener dos copias sincronizadas con SUNAT.

-- ------------------------------------------------------------------------------
-- Terceros: a quién se le cobra y a quién se le paga
-- ------------------------------------------------------------------------------
-- No se reusa `empresa` porque ahí viven los CLIENTES DEL ESTUDIO (las 171). Los
-- terceros son los clientes y proveedores DE cada una de esas empresas, que es otra
-- cosa: el proveedor de un cliente no es cliente del estudio.
CREATE TABLE IF NOT EXISTS `tesoreria_tercero` (
  `id_tercero` INT AUTO_INCREMENT PRIMARY KEY,
  `id_empresa` INT NOT NULL,
  `tipo_documento` ENUM('RUC','DNI','CE','PASAPORTE','SIN_DOC') NOT NULL DEFAULT 'RUC',
  `numero_documento` VARCHAR(15) NULL,
  `razon_social` VARCHAR(200) NOT NULL,
  `nombre_comercial` VARCHAR(200) NULL,
  -- Un mismo tercero suele ser las dos cosas (te vende y le vendés), por eso son dos
  -- banderas y no un ENUM de tipo.
  `es_cliente` TINYINT(1) NOT NULL DEFAULT 0,
  `es_proveedor` TINYINT(1) NOT NULL DEFAULT 0,
  `direccion` VARCHAR(255) NULL,
  `email` VARCHAR(120) NULL,
  `telefono` VARCHAR(30) NULL,
  -- Datos de pago del tercero (cuenta, CCI, Yape). Texto libre a propósito: cambian
  -- seguido y no vale la pena normalizar algo que solo se copia y pega.
  `datos_pago` TEXT NULL,
  `observaciones` VARCHAR(500) NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  `id_usuario_mod` INT NULL,
  UNIQUE KEY `uq_tercero_empresa_doc` (`id_empresa`, `tipo_documento`, `numero_documento`),
  KEY `idx_tercero_empresa` (`id_empresa`, `estado_registro`),
  KEY `idx_tercero_razon` (`razon_social`),
  CONSTRAINT `fk_tercero_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- Medios de pago
-- ------------------------------------------------------------------------------
-- Catálogo global (no lleva id_empresa): "efectivo" o "Yape" significan lo mismo
-- para todas.
CREATE TABLE IF NOT EXISTS `tesoreria_medio_pago` (
  `id_medio_pago` INT AUTO_INCREMENT PRIMARY KEY,
  `codigo` VARCHAR(20) NOT NULL,
  `nombre` VARCHAR(60) NOT NULL,
  -- Si es `0`, el movimiento no toca ninguna cuenta bancaria (efectivo puro).
  `requiere_cuenta` TINYINT(1) NOT NULL DEFAULT 1,
  `orden` INT NOT NULL DEFAULT 0,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  `id_usuario_mod` INT NULL,
  UNIQUE KEY `uq_medio_pago_codigo` (`codigo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- Cuentas de la empresa
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `tesoreria_cuenta` (
  `id_cuenta` INT AUTO_INCREMENT PRIMARY KEY,
  `id_empresa` INT NOT NULL,
  -- FK a planilla_banco (catálogo SUNAT Tabla 36). NULL = caja en efectivo.
  `id_banco` INT NULL,
  `tipo` ENUM('CORRIENTE','AHORROS','DETRACCIONES','EFECTIVO','OTRO') NOT NULL DEFAULT 'CORRIENTE',
  `moneda` ENUM('PEN','USD') NOT NULL DEFAULT 'PEN',
  `numero_cuenta` VARCHAR(30) NULL,
  `cci` VARCHAR(25) NULL,
  `alias` VARCHAR(100) NOT NULL,
  `saldo_inicial` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  -- Saldo corriente, mantenido por el service dentro de la misma transacción que el
  -- movimiento. Se guarda en vez de calcularse con un SUM() cada vez porque el saldo
  -- se muestra en toda pantalla y la tabla de movimientos crece sin límite.
  `saldo_actual` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `observaciones` VARCHAR(500) NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  `id_usuario_mod` INT NULL,
  KEY `idx_cuenta_empresa` (`id_empresa`, `estado_registro`),
  CONSTRAINT `fk_cuenta_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- Movimientos: TODA la plata que entra y sale
-- ------------------------------------------------------------------------------
-- Es el libro único. Un abono a una orden de cobro, un pago a un proveedor y un
-- gasto de caja chica son todos movimientos: si cada módulo llevara su propia tabla,
-- el saldo de la cuenta dependería de sumar cinco lugares y nunca cuadraría.
--
-- `tabla_origen` + `id_registro_origen` dicen QUIÉN generó el movimiento. Van como
-- VARCHAR y no como ENUM a propósito: el ENUM del sistema original obliga a un ALTER
-- cada vez que un módulo nuevo registra plata, y esos ALTER se olvidan.
CREATE TABLE IF NOT EXISTS `tesoreria_movimiento` (
  `id_movimiento` INT AUTO_INCREMENT PRIMARY KEY,
  `id_empresa` INT NOT NULL,
  `id_cuenta` INT NOT NULL,
  `id_tercero` INT NULL,
  `id_medio_pago` INT NULL,
  `tipo` ENUM('INGRESO','EGRESO') NOT NULL,
  `fecha` DATE NOT NULL,
  `monto` DECIMAL(14,2) NOT NULL,
  `moneda` ENUM('PEN','USD') NOT NULL DEFAULT 'PEN',
  -- Solo se llena si la moneda del movimiento no es la de la cuenta.
  `tipo_cambio` DECIMAL(10,4) NULL,
  -- Foto del saldo antes y después. Permite auditar el orden real de los movimientos
  -- y detectar un descuadre sin recalcular la historia entera.
  `saldo_anterior` DECIMAL(14,2) NULL,
  `saldo_posterior` DECIMAL(14,2) NULL,
  `descripcion` VARCHAR(500) NULL,
  `tipo_comprobante` VARCHAR(30) NULL,
  `serie_numero` VARCHAR(50) NULL,
  `ruta_comprobante` VARCHAR(500) NULL,
  `tabla_origen` VARCHAR(50) NULL,
  `id_registro_origen` INT NULL,
  -- ANULADO en vez de borrar: un movimiento anulado tiene que seguir visible con su
  -- motivo, porque el saldo de ese día ya se reportó con él adentro.
  `estado` ENUM('REGISTRADO','ANULADO') NOT NULL DEFAULT 'REGISTRADO',
  `motivo_anulacion` VARCHAR(255) NULL,
  `id_usuario_anula` INT NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  `id_usuario_mod` INT NULL,
  KEY `idx_mov_empresa_fecha` (`id_empresa`, `fecha`),
  KEY `idx_mov_cuenta` (`id_cuenta`, `fecha`),
  KEY `idx_mov_tercero` (`id_tercero`),
  KEY `idx_mov_origen` (`tabla_origen`, `id_registro_origen`),
  CONSTRAINT `fk_mov_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`),
  CONSTRAINT `fk_mov_cuenta` FOREIGN KEY (`id_cuenta`) REFERENCES `tesoreria_cuenta` (`id_cuenta`),
  CONSTRAINT `fk_mov_tercero` FOREIGN KEY (`id_tercero`) REFERENCES `tesoreria_tercero` (`id_tercero`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- Cuentas por COBRAR
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `tesoreria_orden_cobro` (
  `id_orden_cobro` INT AUTO_INCREMENT PRIMARY KEY,
  `id_empresa` INT NOT NULL,
  `codigo_orden` VARCHAR(30) NOT NULL,
  `id_tercero` INT NOT NULL,
  `tipo_transaccion` ENUM('PRODUCTO','SERVICIO','OTRO') NOT NULL DEFAULT 'SERVICIO',
  `tipo_documento` VARCHAR(30) NOT NULL DEFAULT 'FACTURA',
  `serie_numero` VARCHAR(50) NULL,
  `fecha_emision` DATE NOT NULL,
  `fecha_vencimiento` DATE NOT NULL,
  `moneda` ENUM('PEN','USD') NOT NULL DEFAULT 'PEN',
  `monto_total` DECIMAL(14,2) NOT NULL,
  `monto_abonado` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  -- Columna GENERADA: el saldo nunca puede quedar desincronizado del total y lo
  -- abonado, porque no se escribe a mano. Es la diferencia entre confiar en que
  -- todos los caminos de código actualicen bien un campo, y que no haya campo.
  `saldo_pendiente` DECIMAL(14,2) AS (`monto_total` - `monto_abonado`) STORED,
  `estado_orden` ENUM('PENDIENTE','COBRADA_PARCIAL','COBRADA','ANULADA') NOT NULL DEFAULT 'PENDIENTE',
  `descripcion` TEXT NULL,
  `tabla_origen` VARCHAR(50) NULL,
  `id_registro_origen` INT NULL,
  `motivo_anulacion` VARCHAR(255) NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  `id_usuario_mod` INT NULL,
  UNIQUE KEY `uq_cobro_empresa_codigo` (`id_empresa`, `codigo_orden`),
  KEY `idx_cobro_empresa_estado` (`id_empresa`, `estado_orden`),
  KEY `idx_cobro_vencimiento` (`fecha_vencimiento`),
  KEY `idx_cobro_tercero` (`id_tercero`),
  CONSTRAINT `fk_cobro_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`),
  CONSTRAINT `fk_cobro_tercero` FOREIGN KEY (`id_tercero`) REFERENCES `tesoreria_tercero` (`id_tercero`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tesoreria_orden_cobro_cuota` (
  `id_cuota` INT AUTO_INCREMENT PRIMARY KEY,
  `id_orden_cobro` INT NOT NULL,
  `numero_cuota` INT NOT NULL,
  `fecha_vencimiento` DATE NOT NULL,
  `monto_programado` DECIMAL(14,2) NOT NULL,
  `monto_pagado` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `saldo_cuota` DECIMAL(14,2) AS (`monto_programado` - `monto_pagado`) STORED,
  `estado_cuota` ENUM('PENDIENTE','COBRADA_PARCIAL','COBRADA','ANULADA') NOT NULL DEFAULT 'PENDIENTE',
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  UNIQUE KEY `uq_cuota_cobro` (`id_orden_cobro`, `numero_cuota`),
  CONSTRAINT `fk_cuota_cobro` FOREIGN KEY (`id_orden_cobro`) REFERENCES `tesoreria_orden_cobro` (`id_orden_cobro`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Un abono ES un movimiento: por eso `id_movimiento` es UNIQUE y obligatorio. Así no
-- puede existir plata cobrada que no aparezca en el libro, ni el mismo ingreso
-- aplicado dos veces a la misma orden.
CREATE TABLE IF NOT EXISTS `tesoreria_orden_cobro_abono` (
  `id_abono` INT AUTO_INCREMENT PRIMARY KEY,
  `id_orden_cobro` INT NOT NULL,
  `id_cuota` INT NULL,
  `id_movimiento` INT NOT NULL,
  `fecha_cobro` DATE NOT NULL,
  `monto_abonado` DECIMAL(14,2) NOT NULL,
  `descripcion` VARCHAR(500) NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  UNIQUE KEY `uq_abono_movimiento` (`id_movimiento`),
  KEY `idx_abono_orden` (`id_orden_cobro`),
  CONSTRAINT `fk_abono_cobro` FOREIGN KEY (`id_orden_cobro`) REFERENCES `tesoreria_orden_cobro` (`id_orden_cobro`),
  CONSTRAINT `fk_abono_cuota` FOREIGN KEY (`id_cuota`) REFERENCES `tesoreria_orden_cobro_cuota` (`id_cuota`),
  CONSTRAINT `fk_abono_movimiento` FOREIGN KEY (`id_movimiento`) REFERENCES `tesoreria_movimiento` (`id_movimiento`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- Cuentas por PAGAR
-- ------------------------------------------------------------------------------
-- Espejo de cobrar. Se mantienen como dos tablas y no como una sola con un campo
-- "sentido" porque los estados, los reportes y los permisos son distintos, y una
-- tabla única obligaría a filtrar por sentido en cada consulta — justo el filtro que
-- alguien olvida y termina mostrando lo que se debe mezclado con lo que le deben.
CREATE TABLE IF NOT EXISTS `tesoreria_orden_pago` (
  `id_orden_pago` INT AUTO_INCREMENT PRIMARY KEY,
  `id_empresa` INT NOT NULL,
  `codigo_orden` VARCHAR(30) NOT NULL,
  `id_tercero` INT NOT NULL,
  `tipo_transaccion` ENUM('PRODUCTO','SERVICIO','OTRO') NOT NULL DEFAULT 'SERVICIO',
  `tipo_documento` VARCHAR(30) NOT NULL DEFAULT 'FACTURA',
  `serie_numero` VARCHAR(50) NULL,
  `fecha_emision` DATE NOT NULL,
  `fecha_vencimiento` DATE NOT NULL,
  `moneda` ENUM('PEN','USD') NOT NULL DEFAULT 'PEN',
  `monto_total` DECIMAL(14,2) NOT NULL,
  `monto_abonado` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `saldo_pendiente` DECIMAL(14,2) AS (`monto_total` - `monto_abonado`) STORED,
  `estado_orden` ENUM('PENDIENTE','PAGADA_PARCIAL','PAGADA','ANULADA') NOT NULL DEFAULT 'PENDIENTE',
  `descripcion` TEXT NULL,
  `tabla_origen` VARCHAR(50) NULL,
  `id_registro_origen` INT NULL,
  `motivo_anulacion` VARCHAR(255) NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  `id_usuario_mod` INT NULL,
  UNIQUE KEY `uq_pago_empresa_codigo` (`id_empresa`, `codigo_orden`),
  KEY `idx_pago_empresa_estado` (`id_empresa`, `estado_orden`),
  KEY `idx_pago_vencimiento` (`fecha_vencimiento`),
  KEY `idx_pago_tercero` (`id_tercero`),
  CONSTRAINT `fk_pago_empresa` FOREIGN KEY (`id_empresa`) REFERENCES `empresa` (`id_empresa`),
  CONSTRAINT `fk_pago_tercero` FOREIGN KEY (`id_tercero`) REFERENCES `tesoreria_tercero` (`id_tercero`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tesoreria_orden_pago_cuota` (
  `id_cuota` INT AUTO_INCREMENT PRIMARY KEY,
  `id_orden_pago` INT NOT NULL,
  `numero_cuota` INT NOT NULL,
  `fecha_vencimiento` DATE NOT NULL,
  `monto_programado` DECIMAL(14,2) NOT NULL,
  `monto_pagado` DECIMAL(14,2) NOT NULL DEFAULT 0.00,
  `saldo_cuota` DECIMAL(14,2) AS (`monto_programado` - `monto_pagado`) STORED,
  `estado_cuota` ENUM('PENDIENTE','PAGADA_PARCIAL','PAGADA','ANULADA') NOT NULL DEFAULT 'PENDIENTE',
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  UNIQUE KEY `uq_cuota_pago` (`id_orden_pago`, `numero_cuota`),
  CONSTRAINT `fk_cuota_pago` FOREIGN KEY (`id_orden_pago`) REFERENCES `tesoreria_orden_pago` (`id_orden_pago`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `tesoreria_orden_pago_abono` (
  `id_abono` INT AUTO_INCREMENT PRIMARY KEY,
  `id_orden_pago` INT NOT NULL,
  `id_cuota` INT NULL,
  `id_movimiento` INT NOT NULL,
  `fecha_pago` DATE NOT NULL,
  `monto_abonado` DECIMAL(14,2) NOT NULL,
  `descripcion` VARCHAR(500) NULL,
  `estado_registro` ENUM('ACTIVO','ELIMINADO') NOT NULL DEFAULT 'ACTIVO',
  `id_usuario_crea` INT NULL,
  UNIQUE KEY `uq_abono_pago_movimiento` (`id_movimiento`),
  KEY `idx_abono_orden_pago` (`id_orden_pago`),
  CONSTRAINT `fk_abonop_pago` FOREIGN KEY (`id_orden_pago`) REFERENCES `tesoreria_orden_pago` (`id_orden_pago`),
  CONSTRAINT `fk_abonop_cuota` FOREIGN KEY (`id_cuota`) REFERENCES `tesoreria_orden_pago_cuota` (`id_cuota`),
  CONSTRAINT `fk_abonop_movimiento` FOREIGN KEY (`id_movimiento`) REFERENCES `tesoreria_movimiento` (`id_movimiento`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- Semillas
-- ------------------------------------------------------------------------------
