-- <<< FIN BLOQUE GENERADO: planilla_sunat_catalogo



-- ------------------------------------------------------------------------------
-- planilla_banco — se siembra de la Tabla 36, por eso va DESPUÉS del catálogo
-- ------------------------------------------------------------------------------
-- Tiene que correr acá abajo y no junto al resto del paso 2: lee de
-- planilla_sunat_catalogo, que se carga en esta misma sección. Si va antes, el
-- INSERT ... SELECT no encuentra filas y la tabla queda vacía SIN dar error.
INSERT INTO `planilla_banco` (`codigo_sunat`, `nombre`, `formato_telecredito`, `longitud_cci`, `id_usuario_crea`)
SELECT c.codigo, c.descripcion,
       CASE c.codigo
         WHEN '002' THEN 'BCP'
         WHEN '003' THEN 'INTERBANK'
         WHEN '009' THEN 'SCOTIABANK'
         WHEN '011' THEN 'BBVA'
         ELSE 'NINGUNO'
       END,
       20, 1
FROM `planilla_sunat_catalogo` c
WHERE c.tabla_num = 36 AND c.estado_registro = 'ACTIVO'
ON DUPLICATE KEY UPDATE `nombre` = VALUES(`nombre`);


